async function renderNotesPage() {
  const body = document.getElementById('notesBody');
  if (!body) return;
  if (!currentUser || currentUser.role !== 'admin') {
    body.innerHTML = '<div class="empty-note">Teaching Notes are only available to the admin.</div>';
    return;
  }
  body.innerHTML = '<div style="padding:48px;text-align:center;color:var(--text-muted);">Loading your teaching notes…</div>';
  await loadTeachingNotes(true);
  notesRenderBody();
}

