// =====================================================================
// PAGE NAVIGATION (Landing / Login / Register / App)
// =====================================================================
function showPage(pageId) {
  ['landingPage', 'loginPage', 'registerPage', 'appWrapper'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.style.display = id === pageId ? (id === 'appWrapper' ? 'flex' : '') : 'none';
  });
  // Clear error states when switching
  document.querySelectorAll('.auth-error').forEach(e => e.style.display = 'none');
  document.querySelectorAll('.auth-loading').forEach(e => e.classList.remove('active'));
  const fp = document.getElementById('forgotPassInfo');
  if (fp) fp.style.display = 'none';
}

// =====================================================================
// FIREBASE AUTH - Email/Password Login
// =====================================================================
async function handleEmailLogin() {
  // Accepts a real email OR a centre username (mapped to its synthetic email).
  const rawId = document.getElementById('loginEmail').value;
  const candidates = _loginCandidateEmails(rawId);
  const pass = document.getElementById('loginPass').value;
  const errorEl = document.getElementById('loginError');
  const loadingEl = document.getElementById('loginLoading');
  const infoEl = document.getElementById('forgotPassInfo');
  if (infoEl) infoEl.style.display = 'none';

  if (!candidates.length || !pass) {
    errorEl.textContent = 'Please enter both your username (or email) and password';
    errorEl.style.display = 'block';
    return;
  }

  errorEl.style.display = 'none';
  loadingEl.classList.add('active');
  document.getElementById('loginBtn').disabled = true;

  try {
    let cred = null, firstErr = null;
    for (const email of candidates) {
      try { cred = await signInWithEmailAndPassword(auth, email, pass); break; }
      catch (err) {
        if (!firstErr) firstErr = err;
        // Only keep scanning on "no such account / wrong password" — anything
        // else (throttling, network) applies to every candidate equally.
        const c = err && err.code;
        if (c !== 'auth/invalid-credential' && c !== 'auth/user-not-found' && c !== 'auth/wrong-password') { firstErr = err; break; }
      }
    }
    if (!cred) throw (firstErr || new Error('Sign-in failed'));
    const u = (rawId || '').trim().toLowerCase();
    if (u && !u.includes('@')) { try { localStorage.setItem(_loginHintKey(u), cred.user.email); } catch (e) {} }
    // onAuthStateChanged will handle the rest
  } catch (error) {
    loadingEl.classList.remove('active');
    document.getElementById('loginBtn').disabled = false;
    errorEl.textContent = getAuthErrorMessage(error.code);
    errorEl.style.display = 'block';
    setTimeout(() => { errorEl.style.display = 'none'; }, 5000);
  }
}

// "Forgot password?" on the login page. Real emails get Firebase's reset
// email; centre usernames have no inbox, so the student is pointed to their
// teacher (who resets it from the Usage dashboard's 🔑 button).
async function handleForgotPassword() {
  const raw = (document.getElementById('loginEmail').value || '').trim();
  const errorEl = document.getElementById('loginError');
  const infoEl = document.getElementById('forgotPassInfo');
  errorEl.style.display = 'none';
  if (!raw) {
    errorEl.textContent = 'Type your username or email above first, then tap "Reset it"';
    errorEl.style.display = 'block';
    setTimeout(() => { errorEl.style.display = 'none'; }, 5000);
    return;
  }
  if (!raw.includes('@')) {
    infoEl.innerHTML = '🧑‍🏫 Centre usernames don\'t have an email inbox, so ask your <b>teacher</b> to reset your password — it takes them one click and all your XP, gold and progress stay safe.';
    infoEl.style.display = 'block';
    return;
  }
  try {
    await sendPasswordResetEmail(auth, raw);
    infoEl.innerHTML = '📬 Password reset email sent to <b>' + escapeHtml(raw) + '</b> — check your inbox (and spam folder), then sign in with your new password.';
    infoEl.style.display = 'block';
  } catch (error) {
    errorEl.textContent = getAuthErrorMessage(error.code);
    errorEl.style.display = 'block';
    setTimeout(() => { errorEl.style.display = 'none'; }, 5000);
  }
}

// ---- Change my password (signed-in email/password accounts) ----
function openChangePassword() {
  ['cpCurrent', 'cpNew', 'cpConfirm'].forEach(id => { document.getElementById(id).value = ''; });
  document.getElementById('cpError').style.display = 'none';
  document.getElementById('cpLoading').classList.remove('active');
  document.getElementById('cpSaveBtn').disabled = false;
  document.getElementById('changePassOverlay').classList.add('active');
}
function closeChangePassword() {
  document.getElementById('changePassOverlay').classList.remove('active');
}
async function handleChangePassword() {
  const cur = document.getElementById('cpCurrent').value;
  const next = document.getElementById('cpNew').value;
  const confirm2 = document.getElementById('cpConfirm').value;
  const errorEl = document.getElementById('cpError');
  const showErr = msg => { errorEl.textContent = msg; errorEl.style.display = 'block'; };
  errorEl.style.display = 'none';

  if (!cur || !next) return showErr('Please fill in every field');
  if (next !== confirm2) return showErr('New passwords do not match');
  if (next.length < 6) return showErr('New password must be at least 6 characters');
  const user = auth.currentUser;
  if (!user || !user.email) return showErr('You need to be signed in to change your password');
  if (_practiceAs) return showErr('End the practice session first — this would change YOUR password, not ' + (_practiceAs.name || 'the student') + '\'s');

  const loadingEl = document.getElementById('cpLoading');
  loadingEl.classList.add('active');
  document.getElementById('cpSaveBtn').disabled = true;
  try {
    await reauthenticateWithCredential(user, EmailAuthProvider.credential(user.email, cur));
    await updatePassword(user, next);
    closeChangePassword();
    showToast('Password changed ✓ — use the new one next time you sign in', 'success');
  } catch (error) {
    const c = error && error.code;
    showErr(c === 'auth/wrong-password' || c === 'auth/invalid-credential'
      ? 'Current password is incorrect'
      : getAuthErrorMessage(c));
  } finally {
    loadingEl.classList.remove('active');
    document.getElementById('cpSaveBtn').disabled = false;
  }
}

// =====================================================================
// FIREBASE AUTH - Email/Password Registration
// =====================================================================
async function handleEmailRegister() {
  const name = document.getElementById('registerName').value.trim();
  const email = document.getElementById('registerEmail').value.trim();
  const pass = document.getElementById('registerPass').value;
  const passConfirm = document.getElementById('registerPassConfirm').value;
  const errorEl = document.getElementById('registerError');
  const loadingEl = document.getElementById('registerLoading');

  if (!name || !email || !pass) {
    errorEl.textContent = 'Please fill in all fields';
    errorEl.style.display = 'block';
    return;
  }
  if (pass !== passConfirm) {
    errorEl.textContent = 'Passwords do not match';
    errorEl.style.display = 'block';
    return;
  }
  if (pass.length < 6) {
    errorEl.textContent = 'Password must be at least 6 characters';
    errorEl.style.display = 'block';
    return;
  }

  errorEl.style.display = 'none';
  loadingEl.classList.add('active');
  document.getElementById('registerBtn').disabled = true;

  try {
    const userCredential = await createUserWithEmailAndPassword(auth, email, pass);
    await updateProfile(userCredential.user, { displayName: name });
    // onAuthStateChanged will handle the rest
  } catch (error) {
    loadingEl.classList.remove('active');
    document.getElementById('registerBtn').disabled = false;
    errorEl.textContent = getAuthErrorMessage(error.code);
    errorEl.style.display = 'block';
    setTimeout(() => { errorEl.style.display = 'none'; }, 5000);
  }
}

// =====================================================================
// FIREBASE AUTH - Google Sign-In
// =====================================================================
async function handleGoogleSignIn() {
  try {
    // Use signInWithPopup with explicit browserPopupRedirectResolver to handle
    // cross-origin auth (authDomain differs from hosting domain). This avoids
    // the "missing initial state" error from signInWithRedirect on mobile
    // browsers with storage partitioning (Safari ITP, Chrome privacy).
    await signInWithPopup(auth, googleProvider, browserPopupRedirectResolver);
    // onAuthStateChanged will handle the rest
  } catch (error) {
    if (error.code === 'auth/popup-closed-by-user' || error.code === 'auth/cancelled-popup-request') {
      // User closed the popup — do nothing
    } else if (error.code === 'auth/popup-blocked') {
      showToast('Please allow popups for Google Sign-In', 'error');
    } else {
      showToast(getAuthErrorMessage(error.code), 'error');
    }
  }
}

// =====================================================================
// FIREBASE AUTH - Logout
// =====================================================================
async function handleLogout() {
  try {
    _practiceAsClear();          // never hand a practice session to the next person
    _practiceAs = null;
    await signOut(auth);
    try { ainsteinOnSignOut(); } catch (e) {}
    showPage('landingPage');
    showToast('Signed out successfully', 'info');
  } catch (error) {
    showToast('Error signing out', 'error');
  }
}

// =====================================================================
// AUTH ERROR MESSAGES
// =====================================================================
function getAuthErrorMessage(code) {
  const messages = {
    'auth/email-already-in-use': 'An account with this email already exists',
    'auth/invalid-email': 'Please enter a valid email address',
    'auth/operation-not-allowed': 'This sign-in method is not enabled',
    'auth/weak-password': 'Password must be at least 6 characters',
    'auth/user-disabled': 'This account has been disabled',
    'auth/user-not-found': 'No account found with this email',
    'auth/wrong-password': 'Incorrect password',
    'auth/invalid-credential': 'Invalid email or password',
    'auth/too-many-requests': 'Too many attempts. Please try again later',
    'auth/popup-blocked': 'Sign-in popup was blocked. Please allow popups',
    'auth/network-request-failed': 'Network error. Please check your connection',
  };
  return messages[code] || 'An error occurred. Please try again';
}

// =====================================================================
// ADMIN — CREATE STUDENT ACCOUNT
// createUserWithEmailAndPassword signs in the new user on whichever Auth
// instance it runs against, so we run it on a SECONDARY Firebase app —
// the admin's session on the primary app is never touched.
// Students don't need a real email: the admin picks a USERNAME and the
// app stores it as username@STUDENT_USERNAME_DOMAIN behind the scenes
// (Firebase Auth requires an email-shaped string). The login page maps
// a plain username back to that address the same way.
// =====================================================================
const STUDENT_USERNAME_DOMAIN = 'students.sciencequest.app';
// A plain username (no @) becomes its synthetic email; real emails pass through.
function _loginIdToEmail(id) {
  const s = (id || '').trim();
  return s && !s.includes('@') ? s.toLowerCase() + '@' + STUDENT_USERNAME_DOMAIN : s;
}
// After an admin password reset, the student's sign-in lives at
// username.rN@domain (Firebase Auth can't reuse the old address). Login
// therefore tries the base address first, then .r2 … .r9, so the student
// keeps typing the SAME username forever. A per-device hint remembers which
// address worked last, making repeat logins a single attempt.
const RESET_SUFFIX_MAX = 9;
function _loginHintKey(u) { return 'sq_login_email_' + u; }
function _loginCandidateEmails(rawId) {
  const s = (rawId || '').trim();
  if (!s) return [];
  if (s.includes('@')) return [s];
  const u = s.toLowerCase();
  const list = [u + '@' + STUDENT_USERNAME_DOMAIN];
  for (let n = 2; n <= RESET_SUFFIX_MAX; n++) list.push(u + '.r' + n + '@' + STUDENT_USERNAME_DOMAIN);
  let hint = null;
  try { hint = localStorage.getItem(_loginHintKey(u)); } catch (e) {}
  const i = hint ? list.indexOf(hint) : -1;
  if (i > 0) { list.splice(i, 1); list.unshift(hint); }
  return list;
}
let _studentCreator = null; // { auth, db } on the secondary app
function _getStudentCreator() {
  if (!_studentCreator) {
    const app2 = initializeApp(firebaseConfig, 'studentCreator');
    if (RECAPTCHA_SITE_KEY && !RECAPTCHA_SITE_KEY.startsWith("PASTE_")) {
      try {
        initializeAppCheck(app2, {
          provider: new ReCaptchaV3Provider(RECAPTCHA_SITE_KEY),
          isTokenAutoRefreshEnabled: true
        });
      } catch (e) { console.warn('Secondary App Check init failed:', e); }
    }
    _studentCreator = { auth: getAuth(app2), db: getFirestore(app2) };
  }
  return _studentCreator;
}

// The same dialog creates both kinds of account. A student signs in with a bare
// username (there is no email to type at the centre); an employee must use their
// REAL address, because EMPLOYEE_EMAILS is matched on it and a synthetic
// username@students… address would never be recognised as an author.
let _csRole = 'student';
function csSetRole(role) {
  _csRole = role === 'employee' ? 'employee' : 'student';
  const emp = _csRole === 'employee';
  const set = (id, html) => { const el = document.getElementById(id); if (el) el.innerHTML = html; };
  set('csTitle', emp ? 'Create Employee Account' : 'Create Student Account');
  set('csBlurb', emp
    ? 'Set up an account for someone hired to write questions. They sign in with their own email address and get the authoring pages only. You stay signed in as admin.'
    : 'Set up an account for a student practising at your centre. No email needed — just pick a username and password, and the student signs in with them on the login page. You stay signed in as admin.');
  set('csNameLabel', emp ? 'Full name' : 'Student name');
  set('csEmailLabel', emp
    ? 'Email address <span style="font-weight:400;color:var(--text-muted);">(their real one — this is what grants the role)</span>'
    : 'Username <span style="font-weight:400;color:var(--text-muted);">(letters and numbers, no spaces)</span>');
  const idEl = document.getElementById('csEmail');
  if (idEl) idEl.placeholder = emp ? 'e.g. name@gmail.com' : 'e.g. weiming';
  const nameEl = document.getElementById('csName');
  if (nameEl) nameEl.placeholder = emp ? 'e.g. Keertana' : 'e.g. Tan Wei Ming';
  const note = document.getElementById('csEmployeeNote');
  if (note) note.style.display = emp ? '' : 'none';
  const doneLbl = document.getElementById('csDoneEmailLabel');
  if (doneLbl) doneLbl.textContent = emp ? 'Email:' : 'Username:';
  const btn = document.getElementById('csCreateBtn');
  if (btn) btn.textContent = emp ? 'Create Employee Account' : 'Create Account';
}

function openCreateStudent() {
  document.getElementById('csName').value = '';
  document.getElementById('csEmail').value = '';
  document.getElementById('csPass').value = '';
  const radio = document.querySelector('input[name="csRole"][value="student"]');
  if (radio) radio.checked = true;
  csSetRole('student');
  document.getElementById('csError').style.display = 'none';
  document.getElementById('csLoading').classList.remove('active');
  document.getElementById('csCreateBtn').disabled = false;
  document.getElementById('csFormWrap').style.display = '';
  document.getElementById('csSuccessWrap').style.display = 'none';
  document.getElementById('createStudentOverlay').classList.add('active');
}

function closeCreateStudent() {
  document.getElementById('createStudentOverlay').classList.remove('active');
}

// Friendly password the admin can read out at the centre: science word + 4 digits.
function generateStudentPassword() {
  const words = ['comet', 'rocket', 'magnet', 'photon', 'fossil', 'nebula', 'crystal', 'volcano', 'gravity', 'neuron', 'plasma', 'quartz', 'meteor', 'oxygen', 'proton'];
  const w = words[Math.floor(Math.random() * words.length)];
  document.getElementById('csPass').value = w + Math.floor(1000 + Math.random() * 9000);
}

async function handleCreateStudent() {
  const name = document.getElementById('csName').value.trim();
  const username = document.getElementById('csEmail').value.trim().toLowerCase();
  const pass = document.getElementById('csPass').value;
  const errorEl = document.getElementById('csError');
  const showErr = msg => { errorEl.textContent = msg; errorEl.style.display = 'block'; };
  errorEl.style.display = 'none';

  const isEmp = _csRole === 'employee';
  if (!name || !username || !pass) return showErr('Please fill in name, ' + (isEmp ? 'email' : 'username') + ' and password');
  // A real email is also accepted, but the normal case is a plain username.
  if (!username.includes('@') && !/^[a-z0-9][a-z0-9._-]{2,}$/.test(username)) {
    return showErr('Username must be at least 3 characters — letters, numbers, dots, dashes (no spaces)');
  }
  // Firebase Auth itself refuses anything shorter — this is not our rule to relax.
  if (pass.length < 6) return showErr('Password must be at least 6 characters (Firebase will not accept a shorter one)');
  const email = _loginIdToEmail(username);
  if (ADMIN_EMAILS.includes(email)) return showErr('That email belongs to an admin account');
  if (isEmp) {
    if (!username.includes('@')) return showErr('An employee signs in with their real email address, not a username');
    // Default-deny: the role comes from EMPLOYEE_EMAILS, so creating an account
    // for an address that is not on the list would hand them a student account
    // and no way to tell why.
    if (!EMPLOYEE_EMAILS.includes(email)) {
      return showErr('Add ' + email + ' to EMPLOYEE_EMAILS in app.js and deploy first — that list is what grants the authoring role');
    }
  }

  const loadingEl = document.getElementById('csLoading');
  loadingEl.classList.add('active');
  document.getElementById('csCreateBtn').disabled = true;
  try {
    const sc = _getStudentCreator();
    const cred = await createUserWithEmailAndPassword(sc.auth, email, pass);
    try { await updateProfile(cred.user, { displayName: name }); } catch (e) { console.warn('Could not set student name:', e); }
    // Profile doc so the student appears on the dashboard before their first
    // login. Written on the secondary app (as the student), matching the
    // permissions recordLogin relies on.
    try {
      await setDoc(doc(sc.db, 'userProfiles', cred.user.uid), {
        uid: cred.user.uid,
        email: email,
        username: username.includes('@') ? null : username,
        displayName: name,
        // Descriptive only — the live role is decided at sign-in from
        // ADMIN_EMAILS / EMPLOYEE_EMAILS, never from this doc.
        role: isEmp ? 'employee' : 'student',
        createdBy: currentUser ? currentUser.uid : null,
        createdAt: Timestamp.now()
      }, { merge: true });
    } catch (e) { console.warn('Could not write student profile:', e); }
    await signOut(sc.auth); // ends the secondary session only

    document.getElementById('csDoneName').textContent = name;
    document.getElementById('csDoneEmail').textContent = isEmp ? email : username;
    document.getElementById('csDonePass').textContent = pass;
    document.getElementById('csFormWrap').style.display = 'none';
    document.getElementById('csSuccessWrap').style.display = '';
    try { loadUsageDashboard(); } catch (e) {}
  } catch (error) {
    showErr(error && error.code === 'auth/email-already-in-use'
      ? (isEmp ? 'An account already exists for ' + email + ' — they can sign in with it now'
               : 'That username is already taken — try another')
      : getAuthErrorMessage(error.code));
  } finally {
    loadingEl.classList.remove('active');
    document.getElementById('csCreateBtn').disabled = false;
  }
}

function copyStudentCredentials() {
  const txt = 'Science Quest login\nName: ' + document.getElementById('csDoneName').textContent +
    '\n' + (_csRole === 'employee' ? 'Email' : 'Username') + ': ' + document.getElementById('csDoneEmail').textContent +
    '\nPassword: ' + document.getElementById('csDonePass').textContent;
  navigator.clipboard.writeText(txt)
    .then(() => showToast('Login details copied', 'success'))
    .catch(() => showToast('Could not copy — please note the details down', 'error'));
}

// =====================================================================
// ADMIN — RESET A STUDENT'S PASSWORD (unlink & re-issue)
// A browser app can't change another Firebase Auth user's password, so the
// reset UNLINKS instead: a brand-new auth account is created at
// username.rN@domain with the new password, all of the student's progress
// is copied across to it, and the old account is retired. The login page
// scans those .rN addresses (see _loginCandidateEmails), so the student
// keeps signing in with the SAME username they always had.
// =====================================================================
let _resetTarget = null; // { uid, name, username, email }

// Base centre username for an account: strip the synthetic domain and any
// .rN reset suffix; for real emails, sanitise the local part.
function _usernameFromEmail(email) {
  let local = (email || '').toLowerCase().split('@')[0];
  local = local.replace(/\.r[2-9]$/, '');
  return local.replace(/[^a-z0-9._-]/g, '');
}

function openResetStudentLogin(uid) {
  if (!currentUser || currentUser.role !== 'admin') return;
  const s = _usageStudentStats[uid] || {};
  const email = s.email || '';
  const username = _usernameFromEmail(email);
  if (!username || username.length < 3) {
    showToast('This account has no usable username — create a fresh account for the student instead', 'error');
    return;
  }
  _resetTarget = { uid, name: s.name || 'Student', username, email };
  document.getElementById('rlName').textContent = _resetTarget.name;
  document.getElementById('rlUsername').textContent =
    email.toLowerCase().endsWith('@' + STUDENT_USERNAME_DOMAIN) ? username : email;
  document.getElementById('rlPass').value = '';
  document.getElementById('rlError').style.display = 'none';
  document.getElementById('rlLoading').classList.remove('active');
  document.getElementById('rlResetBtn').disabled = false;
  document.getElementById('rlCancelBtn').disabled = false;
  document.getElementById('rlFormWrap').style.display = '';
  document.getElementById('rlSuccessWrap').style.display = 'none';
  document.getElementById('resetLoginOverlay').classList.add('active');
}

function closeResetStudentLogin() {
  document.getElementById('resetLoginOverlay').classList.remove('active');
}

function generateResetPassword() {
  const words = ['comet', 'rocket', 'magnet', 'photon', 'fossil', 'nebula', 'crystal', 'volcano', 'gravity', 'neuron', 'plasma', 'quartz', 'meteor', 'oxygen', 'proton'];
  const w = words[Math.floor(Math.random() * words.length)];
  document.getElementById('rlPass').value = w + Math.floor(1000 + Math.random() * 9000);
}

// Copy one users/{uid}/{col}/{docId} doc from the old account to the new one.
async function _copyUserDoc(scDb, oldUid, newUid, col, docId) {
  try {
    const s = await getDoc(doc(db, 'users', oldUid, col, docId));
    if (s.exists()) await setDoc(doc(scDb, 'users', newUid, col, docId), s.data());
  } catch (e) { console.warn('reset copy ' + col + '/' + docId, e); }
}

async function handleResetStudentLogin() {
  const t = _resetTarget;
  const pass = document.getElementById('rlPass').value;
  const errorEl = document.getElementById('rlError');
  const showErr = msg => { errorEl.textContent = msg; errorEl.style.display = 'block'; };
  errorEl.style.display = 'none';
  if (!currentUser || currentUser.role !== 'admin' || !t) return;
  if (!pass || pass.length < 6) return showErr('New password must be at least 6 characters');

  const loadingEl = document.getElementById('rlLoading');
  const setStep = txt => { document.getElementById('rlLoadingText').textContent = txt; };
  loadingEl.classList.add('active');
  document.getElementById('rlResetBtn').disabled = true;
  document.getElementById('rlCancelBtn').disabled = true;
  const sc = _getStudentCreator();
  try {
    // 1) Old profile — level / avatar / family details come along for the ride.
    let oldProf = {};
    try {
      const s = await getDoc(doc(db, 'userProfiles', t.uid));
      if (s.exists()) oldProf = s.data() || {};
    } catch (e) { console.warn('reset profile read', e); }
    if (oldProf.supersededBy) throw new Error('This sign-in was already reset — reload the usage data and reset the newest entry instead.');

    // 2) Create the replacement sign-in at the next free .rN address.
    setStep('Creating the new sign-in…');
    let cred = null, newEmail = null;
    for (let n = 2; n <= RESET_SUFFIX_MAX && !cred; n++) {
      newEmail = t.username + '.r' + n + '@' + STUDENT_USERNAME_DOMAIN;
      try { cred = await createUserWithEmailAndPassword(sc.auth, newEmail, pass); }
      catch (err) {
        if (!(err && err.code === 'auth/email-already-in-use')) throw err;
      }
    }
    if (!cred) throw new Error('This account has been reset too many times — create a fresh account for the student instead.');
    const newUid = cred.user.uid;
    try { await updateProfile(cred.user, { displayName: t.name }); } catch (e) { console.warn('reset display name', e); }

    // 3) Carry everything over. Reads run as the admin (primary app); writes
    // run as the freshly signed-in student (secondary app) so rules that only
    // allow writing your own documents are still satisfied.
    setStep('Carrying progress over…');
    await setDoc(doc(sc.db, 'userProfiles', newUid), {
      uid: newUid,
      email: newEmail,
      username: t.username,
      displayName: oldProf.displayName || t.name,
      role: 'student',
      level: oldProf.level || null,
      avatar: oldProf.avatar || null,
      students: oldProf.students || null,
      address: oldProf.address || null,
      createdBy: currentUser.uid,
      createdAt: Timestamp.now(),
      resetOf: t.uid
    }, { merge: true });
    await _copyUserDoc(sc.db, t.uid, newUid, 'settings', 'scienceRpg');   // hero XP, gold, streaks
    await _copyUserDoc(sc.db, t.uid, newUid, 'stats', 'performance');     // CER report data
    try {
      const wsSnap = await getDocs(collection(db, 'users', t.uid, 'worksheets'));
      for (const d of wsSnap.docs) await setDoc(doc(sc.db, 'users', newUid, 'worksheets', d.id), d.data());
    } catch (e) { console.warn('reset worksheets copy', e); }
    try {
      const s = await getDoc(doc(db, 'cerLeaderboard', t.uid));
      if (s.exists()) await setDoc(doc(sc.db, 'cerLeaderboard', newUid), Object.assign({}, s.data(), { email: newEmail }));
    } catch (e) { console.warn('reset cer board copy', e); }
    try {
      const s = await getDoc(doc(db, 'scienceGameLeaderboard', t.uid));
      if (s.exists()) await setDoc(doc(sc.db, 'scienceGameLeaderboard', newUid), Object.assign({}, s.data(), { uid: newUid }));
    } catch (e) { console.warn('reset game board copy', e); }

    // Practice history — keeps "unattempted-first" serving and the admin's
    // activity log intact. Batched, 400 writes at a time.
    setStep('Copying practice history…');
    let oldAttemptRefs = [];
    try {
      const aSnap = await getDocs(query(collection(db, 'questionAttempts'), where('uid', '==', t.uid)));
      const docs = aSnap.docs;
      oldAttemptRefs = docs.map(d => d.ref);
      for (let i = 0; i < docs.length; i += 400) {
        const batch = writeBatch(sc.db);
        docs.slice(i, i + 400).forEach(d => {
          const nd = Object.assign({}, d.data(), { uid: newUid });
          if (nd.email) nd.email = newEmail;
          batch.set(doc(collection(sc.db, 'questionAttempts')), nd);
        });
        await batch.commit();
        setStep('Copying practice history… (' + Math.min(i + 400, docs.length) + '/' + docs.length + ')');
      }
    } catch (e) { console.warn('reset attempts copy', e); }

    await signOut(sc.auth); // ends the secondary session only

    // 4) Retire the old sign-in (as admin) so it vanishes from dashboards and
    // can't fork the student's progress if the old password resurfaces.
    setStep('Unlinking the old sign-in…');
    await setDoc(doc(db, 'userProfiles', t.uid), {
      supersededBy: newUid, retired: true, retiredAt: Timestamp.now()
    }, { merge: true });
    // Shared retired map — students' leaderboards read this to hide old entries.
    try {
      await setDoc(doc(db, 'users', currentUser.uid, 'settings', 'retiredAccounts'),
        { uids: { [t.uid]: true } }, { merge: true });
    } catch (e) { console.warn('reset retired map', e); }
    _retiredUidsCache = null; // this session's leaderboard filter picks up the change
    // Best-effort cleanup of the old public docs (rules may forbid — the
    // retired map above keeps them hidden either way).
    try { await deleteDoc(doc(db, 'cerLeaderboard', t.uid)); } catch (e) {}
    try { await deleteDoc(doc(db, 'scienceGameLeaderboard', t.uid)); } catch (e) {}
    try {
      for (let i = 0; i < oldAttemptRefs.length; i += 400) {
        const batch = writeBatch(db);
        oldAttemptRefs.slice(i, i + 400).forEach(r => batch.delete(r));
        await batch.commit();
      }
    } catch (e) { console.warn('reset attempts cleanup', e); }

    // 5) Show the new credentials.
    document.getElementById('rlDoneName').textContent = t.name;
    document.getElementById('rlDoneUser').textContent = t.username;
    document.getElementById('rlDonePass').textContent = pass;
    const note = document.getElementById('rlDoneNote');
    if (t.email && t.email.includes('@') && !t.email.endsWith('@' + STUDENT_USERNAME_DOMAIN)) {
      note.innerHTML = '⚠️ This student used to sign in with <b>' + escapeHtml(t.email) + '</b>. From now on they sign in with the <b>username</b> shown above instead (their old email no longer works here).';
      note.style.display = '';
    } else {
      note.style.display = 'none';
    }
    document.getElementById('rlFormWrap').style.display = 'none';
    document.getElementById('rlSuccessWrap').style.display = '';
    try { loadUsageDashboard(); } catch (e) {}
  } catch (error) {
    console.error('reset student login failed', error);
    try { if (sc.auth.currentUser) await signOut(sc.auth); } catch (e) {}
    showErr(error && error.code ? getAuthErrorMessage(error.code) : (error && error.message) || 'Something went wrong — please try again');
  } finally {
    loadingEl.classList.remove('active');
    document.getElementById('rlResetBtn').disabled = false;
    document.getElementById('rlCancelBtn').disabled = false;
  }
}

function copyResetCredentials() {
  const txt = 'Science Quest login (password reset)\nName: ' + document.getElementById('rlDoneName').textContent +
    '\nUsername: ' + document.getElementById('rlDoneUser').textContent +
    '\nNew password: ' + document.getElementById('rlDonePass').textContent;
  navigator.clipboard.writeText(txt)
    .then(() => showToast('New login details copied', 'success'))
    .catch(() => showToast('Could not copy — please note the details down', 'error'));
}

// =====================================================================
// AUTH STATE LISTENER
// =====================================================================
const ADMIN_EMAILS = ['chungzhikai@gmail.com', 'abigail.yew@stanfordmanpower.com'];
// Super admin sees questions and vetting from every other admin account.
const SUPER_ADMIN_EMAIL = 'chungzhikai@gmail.com';
// ---- Employee accounts ---------------------------------------------------
// A third role between admin and student: someone hired to WRITE QUESTIONS.
// They get the question creator, the bank, the vetting list and the worksheet
// builder, and nothing else — no student data, no usage dashboard, no games,
// no settings. See EMPLOYEE_PAGES for the whole list of pages they can reach.
//
// They have no bank of their own. Everything they author is written straight
// into the teacher's bank (_bankOwnerUid), because a question filed under the
// employee's own uid is a question no student would ever be served.
const EMPLOYEE_EMAILS = ['pkeertana21@gmail.com'];
const EMPLOYEE_PAGES = ['create', 'exampaper', 'bank', 'vetting', 'checkq', 'worksheet', 'myworksheets', 'worksession'];
let adminUid = null; // the bank owner: loaded for student AND employee accounts
// Maps question/vetting id -> owning admin's uid. Populated when super admin
// loads other admins' subcollections so writes/deletes target the right doc.
const _ownerUidByQuestionId = {};
const _ownerUidByVettingId  = {};

// Read the shared config/admin pointer into `adminUid`. Students get this as a
// side effect of loadAdminQuestions; an employee needs it on its own, before
// the bank is touched, because it decides WHICH bank is touched.
async function _resolveBankOwner() {
  try {
    const snap = await getDoc(doc(db, 'config', 'admin'));
    if (snap.exists() && snap.data().uid) adminUid = snap.data().uid;
  } catch (e) { console.warn('bank owner lookup', e); }
  return adminUid;
}

async function recordLogin(user) {
  try {
    const loginRef = collection(db, 'loginEvents');
    await addDoc(loginRef, {
      uid: user.uid,
      email: user.email,
      displayName: user.displayName || user.email.split('@')[0],
      timestamp: Timestamp.now(),
      userAgent: navigator.userAgent
    });
    // Also update the user profile doc with last login
    await setDoc(doc(db, 'userProfiles', user.uid), {
      uid: user.uid,
      email: user.email,
      displayName: user.displayName || user.email.split('@')[0],
      lastLogin: Timestamp.now(),
      role: ADMIN_EMAILS.includes(user.email) ? 'admin' : 'student'
    }, { merge: true });
  } catch (err) {
    console.warn('Could not record login:', err);
  }
}

// =====================================================================
// PRACTICE AS STUDENT — for the centre's own computers
// =====================================================================
// A student visiting the centre practises on a centre computer while the
// admin stays signed in underneath. For the whole session the app simply IS
// that student: every attempt, point, XP, card, level and prize is written to
// their own account exactly as if they had signed in at home, and the student
// sees the ordinary student app (no admin pages).
//
// The switch happens in enterApp() before anything loads, so no admin state is
// ever mixed into the student's session. The choice lives in sessionStorage:
// closing the tab, signing out or pressing "End session" ends it, and only an
// admin account can start one.
const PRACTICE_AS_KEY = 'sq_practice_as';
let _practiceAs = null;   // { uid, email, name } while acting as a student
let _realUser = null;     // the admin actually signed in, while acting
function _practiceAsLoad() {
  try {
    const j = JSON.parse(sessionStorage.getItem(PRACTICE_AS_KEY) || 'null');
    return (j && j.uid && j.email) ? j : null;
  } catch (e) { return null; }
}
function _practiceAsClear() { try { sessionStorage.removeItem(PRACTICE_AS_KEY); } catch (e) {} }

async function enterApp(user) {
  const displayName = user.displayName || user.email.split('@')[0];
  const isAdmin = ADMIN_EMAILS.includes(user.email);
  // An employee is never also an admin — admin wins if an address is in both.
  const isEmployee = !isAdmin && EMPLOYEE_EMAILS.includes(user.email);
  const roleOf = isAdmin ? 'admin' : isEmployee ? 'employee' : 'student';
  // Acting as a student? Only an admin may, and the flag is per-tab.
  const wanted = _practiceAsLoad();
  if (wanted && !isAdmin) _practiceAsClear();
  _practiceAs = (wanted && isAdmin) ? wanted : null;
  _realUser = { uid: user.uid, email: user.email, name: displayName, role: roleOf };
  // While acting, run the STUDENT branch below — the visiting student must get
  // their own app, not the admin's.
  const asAdmin = isAdmin && !_practiceAs;
  // A retired sign-in (its password was reset by the admin) must not fork the
  // student's progress — bounce it back to the login page.
  if (!isAdmin) {
    try {
      const prof = await getDoc(doc(db, 'userProfiles', user.uid));
      if (prof.exists() && prof.data().supersededBy) {
        await signOut(auth);
        showPage('loginPage');
        showToast('Your password was reset — sign in with the new password from your teacher', 'error');
        return;
      }
    } catch (e) { console.warn('superseded check', e); }
  }
  // "Change password" only makes sense for email/password sign-ins (not Google).
  const cpBtn = document.getElementById('changePassBtn');
  // Hidden while acting as a student: it changes the password of the account
  // actually signed in (the admin's), which is never what anyone wants here.
  if (cpBtn) cpBtn.style.display = (!_practiceAs && (user.providerData || []).some(p => p && p.providerId === 'password')) ? '' : 'none';
  currentUser = _practiceAs
    ? { uid: _practiceAs.uid, email: _practiceAs.email, name: _practiceAs.name, role: 'student' }
    : { uid: user.uid, email: user.email, name: displayName, role: roleOf };
  showPage('appWrapper');
  // Record login event for usage tracking. This logs the REAL sign-in (the
  // admin) — a practice session is not a login by the student, and the
  // attendance record should not pretend otherwise.
  recordLogin(user);
  const shownName = currentUser.name;
  document.querySelector('.avatar').textContent = shownName[0].toUpperCase();
  document.querySelector('.sidebar-footer div div:first-child').textContent = shownName;
  practiceAsRenderBar();

  if (asAdmin) {
    // Admin: save UID to config doc so students can find it
    setDoc(doc(db, 'config', 'admin'), { uid: user.uid, email: user.email }).catch(err =>
      console.warn('Could not save admin config:', err)
    );
    configureSidebarForRole('admin');
    publishTopicsForStudents(); // keep the students' shared topic→level map current
    await loadCustomCategories(); // before questions load — the MCQ rule respects custom categories
    await loadFromStorage();
    await loadStudentsFromStorage();
    loadMarkingSettings();
    loadGenSettings();
    loadTeachingNotes(); // grounds AI generation & marking on the uploaded notes
    loadSampleData();
    // Saved worksheets were only ever loaded on the student branch, so an admin
    // who pressed "Save Worksheet" could never find it again — the page was
    // simply never populated for them.
    loadSavedWorksheets().then(renderSavedWorksheets).catch(e => console.warn('saved worksheets', e));
    renderBlocks();
    populatePracticeStudentSelect();
    // Load scheduled questions and auto-release any due ones
    loadScheduledQuestions();
    // Load flagged question count for badge
    loadFlaggedQuestions();
    // Every question ends up with at least one tag: AI-tag the untagged ones
    // in the background (ten workers, metadata fallback — see autoTagAllQuestions).
    autoTagWholeBankInBackground();
    qPartAutoConvertLater();   // typed "a)" markers -> official parts, once per load
    // Warm the image cache in the background so bank / Doctor / Past Papers
    // images show instantly (non-blocking, idle-scheduled).
    warmImageCacheInBackground(questionBank);
    // Prompt student setup only once per user account
    if (!studentSetupSeen) {
      setTimeout(() => openStudentSetup(), 600);
    }
  } else if (isEmployee) {
    // Employee: an author, not a teacher. They get the question creator, the
    // bank, the vetting list and the worksheet builder, working directly on
    // the teacher's bank — so the config/admin pointer, the student roster,
    // the usage dashboard and every game are all deliberately absent here.
    configureSidebarForRole('employee');
    // The bank owner must be resolved BEFORE anything reads or writes it:
    // _bankOwnerUid falls back to the employee's own uid while adminUid is
    // null, and a question saved into that subtree is one no student sees.
    await _resolveBankOwner();
    if (!adminUid) {
      showToast('Could not find the teacher\'s question bank — ask Mr Chung to sign in once, then reload', 'error');
    }
    await loadCustomCategories();      // before the bank, so the MCQ rule sees custom categories
    await loadFromStorage();
    loadMarkingSettings();
    loadGenSettings();
    loadTeachingNotes();               // grounds AI question building on the uploaded notes
    renderBlocks();
    loadSavedWorksheets().then(renderSavedWorksheets).catch(e => console.warn('saved worksheets', e));
    populateWsTopicFilter();
    renderWsQuestions();
    warmImageCacheInBackground(questionBank);
    qPartAutoConvertLater();
  } else {
    // Student: load admin's question bank
    configureSidebarForRole('student');
    await loadAdminQuestions();
    // Assigned level cap + attempt history (drives level-capped, unattempted-first serving)
    await loadStudentLevel();
    loadAttemptStats().catch(e => console.warn('attempt stats prefetch', e));
    // Family profile: apply the saved active student, then always ask who's
    // practising (first login asks for name + level instead).
    await famLoadProfile();
    famApplyActiveStudent();
    // Terms of access first — nothing else may be used until they agree. The
    // bank and images keep loading behind the dialog, so accepting drops
    // straight into a ready app.
    await agreementRequire();
    famShowLoginPopup();
    // Preload all images so they display instantly in practice
    await preloadAllQuestionImages();
    await loadSavedWorksheets();
    populateWsTopicFilter();
    renderWsQuestions();
    renderSavedWorksheets();
    await loadCerPerf();
    // The Home screen rendered before the bank/report finished loading —
    // refresh it now the real numbers are in (if the student is still there).
    if (document.querySelector('#page-home.active')) renderHomePage();
  }

  // Concurrent tabs: the channel every other window is heard on. Bound before
  // the work session picks up, because that session may be shared with a tab
  // that is already open and running the clock.
  try { xtInit(); } catch (e) { console.warn('cross-tab sync init', e); }

  // Work sessions: pick a session left running (minimised tab, closed browser,
  // yesterday evening) back up before anything else can save a question.
  try { wkInit(); } catch (e) { console.warn('work session init', e); }

  rpgInit().then(() => {
    // Hero state carries the streak/day counters the Home screen shows.
    if (document.querySelector('#page-home.active')) renderHomePage();
  }).catch(e => console.warn('rpg init', e));

  // Realm of Embers TCG: load the release flag + card art so the nav item and
  // cards render correctly (admins always see it; students only when released).
  tcgInit().catch(e => console.warn('tcg init', e));

  // Science Strike FPS (fps.html): fully released — show the nav item for
  // every signed-in user and surface the release announcement.
  fpsNavInit().catch(e => console.warn('fps nav init', e));

  // Load message inbox so the unread badge shows on the Messages nav item.
  loadMessages().then(updateMsgBadge).catch(e => console.warn('messages init', e));

  // Load any custom avatar / item art so the hero and shop render the PNG overrides.
  loadRpgArtOverrides().catch(e => console.warn('rpg art init', e));

  // Deep-link: a game tab's "Open in the app" button links to index.html#raiders
  // / #defenders — jump straight to that game page once we're signed in.
  // The practice-reminder email links to index.html#practice so a student lands
  // straight on the practice page in one click.
  const hash = (location.hash || '').replace('#', '');
  if (hash === 'raiders' || hash === 'defenders' || hash === 'spire' || hash === 'legends' || hash === 'slayers' || hash === 'leaderboard') {
    setTimeout(() => { try { navigateTo(hash); } catch (e) {} }, 300);
  } else if (hash === 'practice') {
    setTimeout(() => { try { navigateTo(rpgPracticePage()); } catch (e) {} }, 300);
  }

  // Ai-nstein rides along on every page from here on.
  try { ainsteinOnSignIn(); } catch (e) { console.warn('ainstein init', e); }

  // Revision decks, so the sidebar can say how many cards are waiting without the
  // student having to go and look.
  if (currentUser && currentUser.role === 'student') {
    loadFlashcardDecks().then(fcPaintDueBadge).catch(e => console.warn('flashcards init', e));
  }

  showToast('Welcome, ' + displayName + '!', 'success');
}

// App version shown to admins in the sidebar. BUMP THIS on every change you
// deploy (see CLAUDE.md) so the admin can confirm the latest build is live.
const APP_VERSION = 'v1.298.0';

// =====================================================================
// THE SUBJECT SWITCHER — one student, four subjects (v2.6.0)
//
// Polymath teaches four subjects through four SEPARATE apps. They share a
// Firebase project and a sign-in, and they deliberately share nothing else:
// four question banks, four sets of progress, four topic lists (see "Where the
// data lives"). A student who is taught three of them had no way to get from
// one to another except a bookmark per subject, which on a school Chromebook
// means the one they never bookmarked is the one they stop using.
//
// This is a LINK and nothing more. It is four <a href>s, not a router:
//   • Each app stays reachable at its own URL exactly as before — nothing here
//     gates or redirects anything, so a bookmark, a shared link and a QR code
//     all keep working.
//   • Middle-click and open-in-new-tab behave the way a student expects, which
//     a JS `location.href =` handler would quietly break.
//   • Signing in is per app and unchanged. The uid is the same account in all
//     four (one Firebase project), so switching subject does not mean signing
//     in again.
//
// THE URLS ARE RELATIVE, and that is load-bearing. The four are GitHub Pages
// project sites — polymathlc.github.io/{math,english,chinese,cer} — so they
// are sibling folders on one host, and `../math/` resolves correctly there,
// on a local checkout with the four repos side by side, and on a custom
// domain later, without this file ever naming a domain. An absolute
// https://polymathlc.github.io/... would pin every app to that host on the
// day the centre moves to one of its own.
//
// NOTE the Science app's folder is `cer`, not `science` — that is the repo
// name and it is what the URL really is. The label and the folder differ on
// purpose; do not "fix" one to match the other.
const SUBJECT_KEY = 'science';           // which of the four THIS app is
const SUBJECT_APPS = [
  { key: 'math',    ico: '🔢', label: 'Math',    sub: 'Math Practice',            url: '../math/' },
  { key: 'english', ico: '📕', label: 'English', sub: 'English Learning Portal',  url: '../english/' },
  { key: 'chinese', ico: '📗', label: 'Chinese', sub: '华文 · Chinese Portal',     url: '../chinese/' },
  { key: 'science', ico: '🔬', label: 'Science', sub: 'Science Learning Portal',  url: '../cer/' }
];

function subjectCurrent() {
  return SUBJECT_APPS.find(s => s.key === SUBJECT_KEY) || SUBJECT_APPS[0];
}

// The menu is BUILT from SUBJECT_APPS rather than written out in index.html,
// so a subject added to that list appears in all four apps by editing one line
// in each. The current subject is shown and marked, never dropped: a menu that
// silently omits where you already are leaves a student unable to tell which
// app they are looking at.
function subjectRenderMenu() {
  const menu = document.getElementById('subjectMenu');
  if (!menu) return;
  const rows = SUBJECT_APPS.map(s => {
    const here = s.key === SUBJECT_KEY;
    const body =
      `<span class="subject-ico" aria-hidden="true">${s.ico}</span>` +
      `<span><b>${escapeHtml(s.label)}</b><br><span style="font-size:0.74rem;color:var(--text-muted);">${escapeHtml(s.sub)}</span></span>` +
      (here ? `<span class="subject-tick">You are here</span>` : '');
    // The current app is a <div>, not an <a>: a link back to the page you are
    // already on reloads the app and loses whatever was half-typed.
    return here
      ? `<div class="subject-opt here" role="menuitem" aria-current="page">${body}</div>`
      : `<a class="subject-opt" role="menuitem" href="${escapeHtml(s.url)}">${body}</a>`;
  }).join('');
  menu.innerHTML =
    `<div class="subject-menu-title">Your subjects</div>${rows}` +
    `<div class="subject-menu-foot">Each subject keeps its own questions, progress and worksheets. You stay signed in.</div>`;
}

function subjectToggle(e) {
  if (e) e.stopPropagation();
  const wrap = document.getElementById('subjectSwitch');
  if (!wrap) return;
  const open = !wrap.classList.contains('open');
  wrap.classList.toggle('open', open);
  const btn = document.getElementById('subjectBtn');
  if (btn) btn.setAttribute('aria-expanded', open ? 'true' : 'false');
}
function subjectClose() {
  const wrap = document.getElementById('subjectSwitch');
  if (!wrap || !wrap.classList.contains('open')) return;
  wrap.classList.remove('open');
  const btn = document.getElementById('subjectBtn');
  if (btn) btn.setAttribute('aria-expanded', 'false');
}

// Shown only once someone is signed in — it is fixed to the viewport, so on
// the login screen it would float over the login card belonging to nobody.
function subjectShow() {
  const wrap = document.getElementById('subjectSwitch');
  if (!wrap) return;
  const me = subjectCurrent();
  const ico = document.getElementById('subjectIco');
  const name = document.getElementById('subjectName');
  if (ico) ico.textContent = me.ico;
  if (name) name.textContent = me.label;
  subjectRenderMenu();
  wrap.style.display = '';
}

// Bound ONCE on the document rather than per element: the menu's contents are
// rebuilt, and a listener attached to a row would go with the row it was on.
document.addEventListener('click', subjectClose);
document.addEventListener('keydown', e => { if (e.key === 'Escape') subjectClose(); });
// ---- The always-visible session bar ----
// Staff must never be in any doubt about whose account is being played, so
// this sits above everything until the session ends.
function practiceAsRenderBar() {
  const bar = document.getElementById('practiceAsBar');
  if (!bar) return;
  if (!_practiceAs) { bar.style.display = 'none'; document.body.classList.remove('practising-as'); return; }
  const who = document.getElementById('practiceAsWho');
  const real = document.getElementById('practiceAsReal');
  if (who) who.textContent = _practiceAs.name || _practiceAs.email;
  if (real) real.textContent = (_realUser && _realUser.email) || '';
  bar.style.display = '';
  bar.classList.remove('pa-open');   // always comes back collapsed
  const t = document.getElementById('practiceAsToggle');
  if (t) t.setAttribute('aria-expanded', 'false');
  document.body.classList.add('practising-as');
}

// The bar carries the student's name and the End button at all times; the
// sentence explaining where their progress goes is one tap away, so the pill
// stays out of the way of the page underneath it.
function practiceAsToggleDetail() {
  const bar = document.getElementById('practiceAsBar');
  if (!bar) return;
  const open = bar.classList.toggle('pa-open');
  const t = document.getElementById('practiceAsToggle');
  if (t) t.setAttribute('aria-expanded', open ? 'true' : 'false');
}
function exitPracticeAs() {
  if (!_practiceAs) return;
  const name = _practiceAs.name || _practiceAs.email;
  if (!confirm('End the practice session for ' + name + '?\n\nEverything they earned is already saved to their account. You will go back to your own admin account.')) return;
  _practiceAsClear();
  _practiceAs = null;
  location.reload();
}

// ---- Choosing the account (admin only) ----
let _practiceAsList = null;
async function openPracticeAsPicker() {
  if (!_isAdmin()) { showToast('Only an admin can start a practice session', 'error'); return; }
  const old = document.getElementById('practiceAsOverlay'); if (old) old.remove();
  const o = document.createElement('div');
  o.className = 'confirm-overlay active'; o.id = 'practiceAsOverlay';
  o.addEventListener('click', e => { if (e.target === o) closePracticeAsPicker(); });
  o.innerHTML = '<div class="confirm-dialog" style="max-width:620px;text-align:left;max-height:88vh;display:flex;flex-direction:column;">'
    + '<h3 style="margin-bottom:6px;">🎓 Practise as a student</h3>'
    + '<p style="color:var(--text-muted);font-size:0.85rem;line-height:1.6;margin-bottom:18px;">For the centre\'s computers. Pick the student sitting down to practise and this browser tab becomes <b>their</b> account: every question, <b>point, XP, monster and prize is earned on their own account</b>, just as if they had signed in at home. They see the normal student app — none of your admin pages. Your own account is untouched, and the session ends when you press <b>End session</b>, sign out, or close the tab.</p>'
    + '<input type="text" id="practiceAsSearch" class="form-input" placeholder="Search by name or email…" autocomplete="off" spellcheck="false" oninput="practiceAsFilter()" style="margin-bottom:14px;">'
    + '<div id="practiceAsRows" class="practice-as-rows"><div class="ga-loading" style="text-align:center;padding:24px;">Loading student accounts…</div></div>'
    + '<div class="btn-group" style="justify-content:flex-end;margin-top:18px;">'
    +   '<button class="btn btn-outline" onclick="closePracticeAsPicker()">Cancel</button>'
    + '</div>'
    + '</div>';
  document.body.appendChild(o);
  try {
    const snap = await getDocs(collection(db, 'userProfiles'));
    const rows = [];
    snap.forEach(d => {
      const p = d.data() || {};
      if (!p.uid || !p.email) return;
      if (ADMIN_EMAILS.includes(p.email)) return;        // never act as another admin
      if (p.supersededBy) return;                        // retired sign-ins
      rows.push({
        uid: p.uid, email: p.email,
        name: p.displayName || p.email.split('@')[0],
        last: p.lastLogin && p.lastLogin.toDate ? p.lastLogin.toDate() : null
      });
    });
    rows.sort((a, b) => (b.last ? b.last.getTime() : 0) - (a.last ? a.last.getTime() : 0) || a.name.localeCompare(b.name));
    _practiceAsList = rows;
  } catch (e) {
    console.error('practice-as list', e);
    _practiceAsList = [];
    const host = document.getElementById('practiceAsRows');
    if (host) host.innerHTML = '<div class="empty-note">Could not load the student accounts — check your connection and try again.</div>';
    return;
  }
  practiceAsFilter();
}
function closePracticeAsPicker() { const o = document.getElementById('practiceAsOverlay'); if (o) o.remove(); }
function practiceAsFilter() {
  const host = document.getElementById('practiceAsRows');
  if (!host || !_practiceAsList) return;
  const q = ((document.getElementById('practiceAsSearch') || {}).value || '').trim().toLowerCase();
  const list = q ? _practiceAsList.filter(r => (r.name + ' ' + r.email).toLowerCase().includes(q)) : _practiceAsList;
  if (!list.length) { host.innerHTML = '<div class="empty-note">' + (q ? 'No account matches “' + escapeHtml(q) + '”.' : 'No student accounts yet.') + '</div>'; return; }
  host.innerHTML = list.slice(0, 200).map(r =>
    '<div class="practice-as-row">'
    + '<div class="practice-as-who">'
    +   '<b>' + escapeHtml(r.name) + '</b>'
    +   '<span>' + escapeHtml(r.email) + '</span>'
    +   '<span class="dim">' + (r.last ? 'last signed in ' + r.last.toLocaleDateString() : 'never signed in') + '</span>'
    + '</div>'
    + '<button type="button" class="btn btn-primary" onclick="startPracticeAs(\'' + r.uid + '\')">Practise as this account</button>'
    + '</div>').join('')
    + (list.length > 200 ? '<div class="empty-note">Showing the 200 most recent — search to narrow it down.</div>' : '');
}
async function startPracticeAs(uid) {
  if (!_isAdmin()) return;
  const p = (_practiceAsList || []).find(x => x.uid === uid);
  if (!p) return;
  if (!confirm('Practise as ' + p.name + ' (' + p.email + ')?\n\n'
    + 'Everything done from now on — questions answered, points, XP, monsters, prizes — is saved to THEIR account.\n\n'
    + 'Press "End session" on the bar at the bottom when they are finished.')) return;
  // Make sure this admin account can actually write to the student's data
  // before handing the computer over. Without this check a rules failure would
  // only show up later as progress quietly saving nowhere.
  const probe = doc(db, 'users', p.uid, 'settings', 'practiceProbe');
  try {
    await setDoc(probe, { at: new Date().toISOString(), by: (currentUser && currentUser.email) || '' }, { merge: true });
    try { await deleteDoc(probe); } catch (e) { /* leaving the tiny probe doc behind is harmless */ }
  } catch (e) {
    console.error('practice-as write probe failed', e);
    alert('Cannot start the session: your account is not allowed to write to ' + p.name + '\'s data, so nothing they earned would be saved.\n\n'
      + 'Ask for the Firestore rules to allow admin writes to users/{uid}, then try again.\n\n(' + ((e && e.message) || e) + ')');
    return;
  }
  try { sessionStorage.setItem(PRACTICE_AS_KEY, JSON.stringify({ uid: p.uid, email: p.email, name: p.name })); }
  catch (e) { alert('This browser will not let me remember the practice session (private mode?).'); return; }
  closePracticeAsPicker();
  location.reload();      // reload so the whole app starts up as that student
}

function configureSidebarForRole(role) {
  const vb = document.getElementById('appVersionBadge');
  if (vb) vb.textContent = APP_VERSION;
  // Every signed-in path — admin, employee and student — comes through here,
  // which is why the subject switcher is turned on from this one place rather
  // than from three call sites that could drift apart. It is shown to ALL
  // three roles: a student needs it to reach their other subjects, and an
  // author moving between the four banks needs it just as much.
  subjectShow();
  ensureMobileToggles();
  loadCustomTopics();
  rebuildTopicSelect();
  const adminItems = document.querySelectorAll('.admin-only');
  const studentItems = document.querySelectorAll('.student-only');
  if (role === 'employee') {
    // Default-deny: hide every nav item, then show back only the pages on
    // EMPLOYEE_PAGES. Adding a nav item elsewhere in the app therefore cannot
    // silently grant an employee access to it.
    studentItems.forEach(el => el.style.display = 'none');
    document.querySelectorAll('.nav-item').forEach(el => {
      el.style.display = EMPLOYEE_PAGES.indexOf(el.dataset.page || '') >= 0 ? '' : 'none';
    });
    // The section headings ("Build", "Manage", …) are flat siblings of the
    // items, not wrappers, so there is no way to tell which survive. With five
    // items the menu reads perfectly well as one list — hide them all rather
    // than leave a heading standing over nothing.
    document.querySelectorAll('.nav-section-label').forEach(el => el.style.display = 'none');
    document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
    try { navBookmarksInit(); } catch (e) { console.warn('bookmarks', e); }
    navigateTo('create');
    return;
  }
  if (role === 'admin') {
    adminItems.forEach(el => el.style.display = '');
    studentItems.forEach(el => el.style.display = 'none');
    // Ensure create page is default active
    document.querySelectorAll('.nav-item').forEach(n => n.classList.remove('active'));
    const createNav = document.querySelector('.nav-item[data-page="create"]');
    if (createNav) createNav.classList.add('active');
    document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
    const createPage = document.getElementById('page-create');
    if (createPage) createPage.classList.add('active');
  } else {
    adminItems.forEach(el => el.style.display = 'none');
    studentItems.forEach(el => el.style.display = '');
    // Set the Home page as default active for students
    document.querySelectorAll('.nav-item').forEach(n => n.classList.remove('active'));
    const homeNav = document.querySelector('.nav-item[data-page="home"]');
    if (homeNav) homeNav.classList.add('active');
    document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
    const homePage = document.getElementById('page-home');
    if (homePage) homePage.classList.add('active');
  }
  // Stars go on AFTER the role has decided which items exist, so a bookmark can
  // never resurrect an item this account isn't allowed to see.
  try { navBookmarksInit(); } catch (e) { console.warn('bookmarks', e); }
  // Students land on their simple Home screen; admins keep Community. Also
  // start the realtime quest watch so the countdown chip works on every page.
  try { commStartGlobalWatch(); } catch (_) {}
  try { navigateTo(role === 'admin' ? 'community' : 'home'); } catch (_) {}
}

// =====================================================================
// SIDEBAR BOOKMARKS
//
// The sidebar runs to forty-odd items across authoring, practice, games and
// reports. A child uses four of them. Starring an item mirrors it into a gold
// band pinned at the top of the menu.
//
// Mirrored, not moved: the original stays exactly where it was. An item that
// jumps to the top of a menu is an item you can no longer find by memory the
// next time you look for it in its old place.
//
// Stored per account, so one child's shortcuts don't turn up on a sibling's
// login on the same device.
// =====================================================================
function _navBmKey() { return 'navBookmarks:' + ((currentUser && currentUser.uid) || 'anon'); }
function _navBmLoad() {
  try {
    const a = JSON.parse(localStorage.getItem(_navBmKey()) || '[]');
    return Array.isArray(a) ? a.filter(x => typeof x === 'string') : [];
  } catch (_) { return []; }
}
function _navBmSave(list) {
  try { localStorage.setItem(_navBmKey(), JSON.stringify(list)); } catch (_) {}
}
function navBookmarkToggle(page, ev) {
  if (ev) { ev.preventDefault(); ev.stopPropagation(); }   // starring must not navigate
  if (!page) return;
  const list = _navBmLoad();
  const i = list.indexOf(page);
  if (i >= 0) list.splice(i, 1); else list.push(page);     // newest starred goes last
  _navBmSave(list);
  navBookmarksRender();
  showToast(i >= 0 ? 'Removed from Bookmarks' : '⭐ Added to Bookmarks', 'info');
}
// One star per real nav item (never on the mirrored copies — those get their
// own, wired to the same toggle).
function _navBmAddStar(item, page) {
  if (!item || item.querySelector(':scope > .nav-star')) return;
  const b = document.createElement('button');
  b.type = 'button';
  b.className = 'nav-star';
  b.setAttribute('data-star', page);
  b.setAttribute('aria-label', 'Bookmark this');
  b.textContent = '☆';
  b.addEventListener('click', e => navBookmarkToggle(page, e));
  item.appendChild(b);
}
function navBookmarksRender() {
  const wrap = document.getElementById('navBookmarks');
  const list = document.getElementById('navBookmarksList');
  if (!wrap || !list) return;
  const saved = _navBmLoad();
  // An item hidden by role (or by the "hide game" toggle) must not come back
  // through the bookmark band.
  const sources = saved
    .map(p => ({ page: p, el: document.querySelector('.sidebar-nav > .nav-item[data-page="' + CSS.escape(p) + '"]') }))
    .filter(x => x.el && x.el.style.display !== 'none');

  list.innerHTML = '';
  sources.forEach(({ page, el }) => {
    const copy = el.cloneNode(true);          // keeps the icon, the label and the onclick
    copy.classList.remove('active');
    copy.querySelectorAll('.badge').forEach(b => b.remove());   // counts belong to the original
    const oldStar = copy.querySelector('.nav-star');
    if (oldStar) oldStar.remove();
    const star = document.createElement('button');
    star.type = 'button';
    star.className = 'nav-star on';
    star.setAttribute('aria-label', 'Remove from Bookmarks');
    star.textContent = '★';
    star.addEventListener('click', e => navBookmarkToggle(page, e));
    copy.appendChild(star);
    list.appendChild(copy);
  });
  wrap.classList.toggle('show', sources.length > 0);

  // Light up the stars on the originals.
  document.querySelectorAll('.sidebar-nav > .nav-item > .nav-star').forEach(s => {
    const on = saved.includes(s.getAttribute('data-star'));
    s.classList.toggle('on', on);
    s.textContent = on ? '★' : '☆';
    s.setAttribute('aria-label', on ? 'Remove from Bookmarks' : 'Bookmark this');
  });
  _navBmSyncActive();
}
// Keep the mirrored copy highlighted along with its original.
function _navBmSyncActive() {
  const cur = document.querySelector('.sidebar-nav > .nav-item.active');
  const page = cur ? cur.getAttribute('data-page') : '';
  document.querySelectorAll('#navBookmarksList .nav-item').forEach(c => {
    c.classList.toggle('active', !!page && c.getAttribute('data-page') === page);
  });
}
function navBookmarksInit() {
  document.querySelectorAll('.sidebar-nav > .nav-item[data-page]').forEach(item => {
    _navBmAddStar(item, item.getAttribute('data-page'));
  });
  navBookmarksRender();
}

// Every admin account's uid, primary admin (config/admin) first. Approved
// questions live in their ORIGINAL owner's bank (see _qRef/_ownerUidByQuestionId),
// so content is spread across the admin accounts — the super admin loads the
// union, and students must load the same union or a question attached to a
// past paper by one admin shows "attached" to admins but "not available" to
// students. Discovery failures are non-fatal: we always keep the primary uid.
let _allAdminUidsCache = null;
async function allAdminUids() {
  if (_allAdminUidsCache) return _allAdminUidsCache;
  const uids = adminUid ? [adminUid] : [];
  try {
    const profilesSnap = await getDocs(collection(db, 'userProfiles'));
    profilesSnap.forEach(d => {
      const p = d.data();
      if (p && p.uid && ADMIN_EMAILS.includes(p.email) && !uids.includes(p.uid)) uids.push(p.uid);
    });
  } catch (e) { console.warn('admin uid discovery', e); }
  _allAdminUidsCache = uids;
  return uids;
}

async function loadAdminQuestions() {
  try {
    // First, get admin UID from config
    const configSnap = await getDoc(doc(db, 'config', 'admin'));
    if (!configSnap.exists()) {
      showToast('Admin has not set up the question bank yet', 'error');
      return;
    }
    adminUid = configSnap.data().uid;
    try { _startCreditResetListener(); } catch (e) {}
    try { _startDuelClawbackListener(); } catch (e) {}
    try { _startHeroOpsListener(); } catch (e) {}
    // Use the ADMIN's topic→level map (custom topics + removals) so custom
    // topics get their real level on student devices instead of the P6 default.
    try {
      const topicsSnap = await getDoc(doc(db, 'users', adminUid, 'settings', 'topics'));
      if (topicsSnap.exists()) {
        const t = topicsSnap.data();
        customTopics = (t && typeof t.custom === 'object' && t.custom) ? t.custom : {};
        removedTopics = Array.isArray(t && t.removed) ? t.removed : [];
      }
    } catch (e) { console.warn('shared topics load', e); }
    // Admin's custom categories, before questions normalize (the MCQ rule
    // respects custom categories) — also fills the student-side filters.
    await loadCustomCategories();
    // Load questions from EVERY admin account's subcollection (primary admin
    // first, deduped by id) — the same union the super admin sees. Approved
    // questions stay in their original owner's bank, so loading only one
    // admin's collection hides the other admin's questions from students.
    questionBank = [];
    const seenIds = new Set();
    for (const uid of await allAdminUids()) {
      try {
        const qSnap = await getDocs(collection(db, 'users', uid, 'questions'));
        qSnap.forEach(d => {
          const q = d.data();
          if (q && q.id && !seenIds.has(q.id)) {
            seenIds.add(q.id);
            questionBank.push(normalizeLoadedQuestion(q));
          }
        });
      } catch (e) { console.warn('bank load for admin', uid, e); }
    }
    updateCounts();
    populateWsTopicFilter();
    loadMarkingSettings(); // pick up the teacher's rubric for student practice
    loadTeachingNotes();   // teacher's notes ground the AI marking on this device too
  } catch (err) {
    console.error('loadAdminQuestions failed:', err);
    showToast('Could not load questions - check your connection', 'error');
  }
}

onAuthStateChanged(auth, (user) => {
  if (user) {
    enterApp(user);
  } else {
    currentUser = null;
    rpgOnSignOut();
    students = [];
    studentSetupSeen = false;
    // A revision deck and a mistake log belong to one account — never let a
    // sibling signing in on the same device see them.
    fcDecks = [];
    fcRun = null;
    mistakeLog = [];
    _mistakeLogAt = 0;
    try { _fcGapSel.clear(); } catch (_) {}
    try { fcPaintDueBadge(); } catch (_) {}
    showPage('landingPage');
  }
});

// =====================================================================
// STATE MANAGEMENT
// =====================================================================
let currentUser = null;
let blocks = [];
let blockIdCounter = 0;
let questionBank = [];
let vettingList = [];
// Rapid add: live placeholder cards for screenshots still being processed in the
// background. Each: { id, status:'processing'|'error', title, sub, error }.
let rapidJobs = [];
let _rapidSeq = 0;
let _rapidAddedCount = 0;
// IDs of questions added via Rapid add this session — highlighted in the vetting
// grid with a badge + "Open in editor" link. Session-only; never saved to Firestore.
let _rapidJustAdded = new Set();
let selectedBlanks = {}; // { blockId: { wordIndex: true } }
let currentEditingQuestion = null;
let _skipCreateReset = false;
// When an edit is launched from the Past Papers page, we return there (not the
// Question Bank) after saving/cancelling — so the admin never has to hunt for
// the question in the database. _ppReturnFocus remembers WHICH past-paper item
// so we can scroll it back into view (the "specific segment").
let _editReturnPage = null;
let _ppReturnFocus = null;
// Same idea for the Vetting List: when an edit starts there, we go back to the
// list afterwards with the exact same view — _vetReturnScroll is the window
// scroll position to restore, _vetReturnFocus the card to flash.
let _vetReturnScroll = 0;
let _vetReturnFocus = null;
function editQuestionFromPapers(bankId, ppItemId) { editQuestion(bankId); _editReturnPage = 'papers'; _ppReturnFocus = ppItemId || null; _syncBackToPapersBtn(); }
function _afterEditNavigate() {
  const dest = _editReturnPage || 'bank';
  _editReturnPage = null;
  navigateTo(dest);
  if (dest === 'vetting') _vetFocusScroll();
  // An edit launched from a worksheet preview reopens that preview, so the
  // teacher lands back on the sheet they were checking rather than a page list.
  if (dest === 'myworksheets') _wsQeReopenPreview();
  else if (dest === 'worksheet' && wsSelectedIds.size) openWorksheetPreview();
}
function _syncBackToPapersBtn() {
  const b = document.getElementById('backToPapersBtn');
  if (!b) return;
  if (_editReturnPage === 'papers') {
    b.style.display = '';
    b.innerHTML = '&larr; Back to PSLE Papers';
    b.title = 'Return to the PSLE Papers page, right where you left off';
  } else if (_editReturnPage === 'vetting') {
    b.style.display = '';
    b.innerHTML = '&larr; Back to Vetting List';
    b.title = 'Return to the Vetting List, right where you left off';
  } else if (_editReturnPage === 'myworksheets' || _editReturnPage === 'worksheet') {
    b.style.display = '';
    b.innerHTML = '&larr; Back to the worksheet';
    b.title = 'Return to the worksheet preview you were checking';
  } else if (_editReturnPage === 'checkq') {
    b.style.display = '';
    b.innerHTML = '&larr; Back to Check Questions';
    b.title = 'Return to the check queue, on the same question';
  } else {
    b.style.display = 'none';
  }
}
// The top-left "← Back to Past Papers" affordance while editing a paper's
// question — reuses the same discard-confirm + return as Cancel.
function backToPapers() { cancelEdit(); }

// MCQ options are numbered 1,2,3,4 everywhere (matching the mini-games). The
// AI (or a student's handwritten paper) may still answer with a legacy letter
// — normalise "B" → "2", "(3)" → "3", etc.
function _normMcqChoice(raw) {
  const s = String(raw || '').trim().toUpperCase();
  if (!s) return '';
  const digits = s.match(/\d+/);
  if (digits) return digits[0];
  const ch = s.charAt(0);
  if (ch >= 'A' && ch <= 'H') return String(ch.charCodeAt(0) - 64); // A→1 … H→8
  return ch;
}

function normalizeCategoryValue(category) {
  const legacyCER = new Set([
    'CER (Open Ended)',
    'CER (Fill in Blanks)',
    'CER (MCQ)',
    'Open Ended',
    'MCQ'
  ]);
  if (legacyCER.has(category)) return 'CER';
  return category || 'CER';
}

// ── Secondary classifier support ──────────────────────────────────────────
// A question may carry an optional 2nd topic (q.topic2) and 2nd category
// (q.category2) so it can be filed under two skills/topics at once — e.g. a
// question that is BOTH "PSLE - MCQ" and "Reliability". All list-building,
// filtering, matching, searching and display below treat the primary and
// secondary values as a small set.
function qSecondaryTopic(q) { return (q && typeof q.topic2 === 'string') ? q.topic2.trim() : ''; }
function qSecondaryCategory(q) {
  const c = (q && typeof q.category2 === 'string') ? q.category2.trim() : '';
  return c ? normalizeCategoryValue(c) : '';
}
function qTopicList(q) {
  const out = [];
  [((q && q.topic) || ''), qSecondaryTopic(q)].forEach(t => { t = (t || '').trim(); if (t && !out.includes(t)) out.push(t); });
  return out;
}
function qCategoryList(q) {
  const out = [];
  [normalizeCategoryValue(q && q.category), qSecondaryCategory(q)].forEach(c => { if (c && !out.includes(c)) out.push(c); });
  return out;
}
function qMatchesTopic(q, t) { return !t ? true : qTopicList(q).includes(t); }
function qMatchesCategory(q, c) { return !c ? true : qCategoryList(q).includes(c); }

// ── Tags ─────────────────────────────────────────────────────────────────────
// Free-text labels the admin puts on a question for the thing it ACTUALLY tests:
// "elastic spring force", "water displacement", "shadow size". Topic is the
// syllabus bucket and there are twenty-one of them; a tag is as fine-grained as
// the teacher wants, and there is no fixed list.
//
// They earn their keep in three places: the bank's search and its tag filter,
// Ai-nstein's question retrieval (an exact tag match beats every other kind of
// match — it is a human saying "this question is about this"), and any counting
// or sorting done from the outside, because the field is a plain array of strings
// on the question document.
//
// Stored as `tags: string[]`. Kept case-as-typed for display but compared
// case-insensitively, so "Elastic Spring Force" and "elastic spring force" are
// one tag and the admin never has to remember which they used last.
const TAG_MAX_LEN = 48;     // one tag
const TAG_MAX_COUNT = 24;   // tags on one question
function qTagList(q) {
  const raw = (q && Array.isArray(q.tags)) ? q.tags : [];
  const out = [], seen = new Set();
  raw.forEach(t => {
    const s = String(t == null ? '' : t).replace(/\s+/g, ' ').trim().slice(0, TAG_MAX_LEN);
    if (!s) return;
    if (/^\d+$/.test(s)) return;   // a question number is not a concept — the AI does offer these
    const k = s.toLowerCase();
    if (seen.has(k)) return;
    seen.add(k);
    out.push(s);
  });
  return out.slice(0, TAG_MAX_COUNT);
}
// Parse the editor's comma-separated box (newlines count as commas too, so a
// pasted list works) into the stored array.
function parseTagInput(text) {
  return qTagList({ tags: String(text == null ? '' : text).split(/[,\n;]+/) });
}
function tagsToInput(q) { return qTagList(q).join(', '); }
function qMatchesTag(q, t) {
  if (!t) return true;
  const k = String(t).trim().toLowerCase();
  return qTagList(q).some(x => x.toLowerCase() === k);
}
// Every tag in use, with how many questions carry it. Case-insensitively merged;
// the spelling shown is the one used most often, so the autocomplete offers the
// house spelling rather than whichever variant happens to sort first.
function allBankTags(pool) {
  const list = Array.isArray(pool) ? pool : (Array.isArray(questionBank) ? questionBank : []);
  const byKey = new Map();
  list.forEach(q => qTagList(q).forEach(t => {
    const k = t.toLowerCase();
    const rec = byKey.get(k) || { key: k, n: 0, spellings: new Map() };
    rec.n++;
    rec.spellings.set(t, (rec.spellings.get(t) || 0) + 1);
    byKey.set(k, rec);
  }));
  return Array.from(byKey.values()).map(r => {
    let best = '', bestN = -1;
    r.spellings.forEach((n, s) => { if (n > bestN) { bestN = n; best = s; } });
    return { tag: best, key: r.key, n: r.n };
  }).sort((a, b) => (b.n - a.n) || a.key.localeCompare(b.key));
}

// ---- the editor's tag box --------------------------------------------------
// Two rows under the input. The first shows how the typing actually PARSED, with
// how many questions already carry each tag — that number is the whole point,
// because a tag spelled two ways is two tags and splits the very count it exists
// to produce. The second offers the tags already in use, one tap each: no
// datalist, because picking from one replaces the entire comma-separated value.
const TAG_REUSE_SHOWN = 16;
let _tagReuseAll = false;

function renderQuestionTagsUi() {
  const input = document.getElementById('questionTags');
  const prev = document.getElementById('questionTagsPreview');
  const reuse = document.getElementById('questionTagsReuse');
  if (!input || !prev || !reuse) return;
  const chosen = parseTagInput(input.value);
  const chosenKeys = new Set(chosen.map(t => t.toLowerCase()));
  const all = allBankTags();
  const counts = new Map(all.map(r => [r.key, r.n]));

  if (!chosen.length) { prev.style.display = 'none'; prev.innerHTML = ''; }
  else {
    prev.style.display = 'flex';
    prev.innerHTML = chosen.map(t => {
      const n = counts.get(t.toLowerCase()) || 0;
      const note = n ? n + ' question' + (n === 1 ? '' : 's') + ' in the bank already carry this tag'
                     : 'A new tag — nothing else uses it yet';
      return '<span class="qtag-chip' + (n ? '' : ' fresh') + '" title="' + escapeHtml(note) + '">' +
        escapeHtml(t) + '<b>' + (n || 'new') + '</b></span>';
    }).join('');
  }

  // Offer the ones already in use, most-used first, minus what is already on.
  const pool = all.filter(r => !chosenKeys.has(r.key));
  if (!pool.length) { reuse.style.display = 'none'; reuse.innerHTML = ''; return; }
  const shown = _tagReuseAll ? pool : pool.slice(0, TAG_REUSE_SHOWN);
  const more = pool.length - shown.length;
  reuse.style.display = 'block';
  reuse.innerHTML = '<div class="qtag-reuse-label">Tags you\'ve used before — tap to add</div>' +
    '<div class="qtag-row">' +
      shown.map(r => '<button type="button" class="qtag-pick" onclick="questionTagAdd(' + JSON.stringify(r.tag).replace(/"/g, '&quot;') + ')" title="' +
        escapeHtml(r.n + ' question' + (r.n === 1 ? '' : 's') + ' tagged this') + '">' +
        escapeHtml(r.tag) + '<b>' + r.n + '</b></button>').join('') +
      (more > 0 ? '<button type="button" class="qtag-pick more" onclick="questionTagsShowAll()">+' + more + ' more…</button>' : '') +
      (_tagReuseAll && pool.length > TAG_REUSE_SHOWN ? '<button type="button" class="qtag-pick more" onclick="questionTagsShowFewer()">Show fewer</button>' : '') +
    '</div>';
}
function onQuestionTagsInput() { renderQuestionTagsUi(); }
function questionTagAdd(tag) {
  const input = document.getElementById('questionTags');
  if (!input) return;
  const list = parseTagInput(input.value);
  if (!list.some(t => t.toLowerCase() === String(tag).toLowerCase())) list.push(tag);
  input.value = list.join(', ');
  renderQuestionTagsUi();
  input.focus();
}
function questionTagsShowAll() { _tagReuseAll = true; renderQuestionTagsUi(); }
function questionTagsShowFewer() { _tagReuseAll = false; renderQuestionTagsUi(); }
// Every place the editor is (re)filled goes through this, so there is one way to
// set the box and the two rows can never fall out of step with it.
function setQuestionTagsField(q) {
  const input = document.getElementById('questionTags');
  if (input) input.value = q ? tagsToInput(q) : '';
  _tagReuseAll = false;
  renderQuestionTagsUi();
}

// ---- letting the AI propose tags -------------------------------------------
// The value of a tag is that every question about one idea carries the SAME
// string. So the model is not asked to invent a vocabulary — it is handed the one
// the admin has already built and told to reuse it, and anything it returns is
// snapped back onto an existing tag where the two are the same words in a
// different order or a different case ("spring elastic force" → "elastic spring
// force"). New tags are still allowed, because a genuinely new idea needs one; they
// just have to earn it.
function _tagWordKey(s) {
  return _docNorm(s).split(' ').filter(Boolean).sort().join(' ');
}
// Snap a whole list against the bank's current vocabulary. Applied wherever tags
// are STORED — the editor's save, bulk add, and the AI paths — never while someone
// is typing. So the box shows exactly what they wrote, and what lands on the
// question is the spelling the bank already uses. Without this, one admin typing
// "Heat Conduction" quietly forks every count away from "heat conduction".
function _snapTagsToBank(tags) {
  const known = allBankTags().map(r => r.tag);
  const out = [];
  (tags || []).forEach(t => {
    const s = _snapToKnownTag(t, known);
    if (s && !out.some(x => x.toLowerCase() === s.toLowerCase())) out.push(s);
  });
  return out;
}
// Fold a proposed tag onto an existing one where they are the same words. Returns
// the house spelling, or the proposal untouched when it is genuinely new.
function _snapToKnownTag(tag, known) {
  const t = String(tag || '').trim();
  if (!t) return '';
  const lower = t.toLowerCase();
  for (const k of known) if (k.toLowerCase() === lower) return k;      // same string
  const wk = _tagWordKey(t);
  if (!wk) return t;
  for (const k of known) if (_tagWordKey(k) === wk) return k;          // same words
  return t;
}

// Ask the model for tags for ONE question. Returns an array — possibly empty. The
// caller decides what to do with them; nothing is applied here.
async function aiSuggestTags(q) {
  if (!window.__aiReady || !window.__aiReady()) throw new Error('the AI is not ready yet');
  if (!q) return [];
  // Most-used tags first (allBankTags sorts by count), capped so the prompt does
  // not grow with the bank — an uncapped vocabulary makes a whole-bank pass cost
  // quadratic input tokens. Same trick as the screenshot-import prompt.
  const known = allBankTags().slice(0, 150).map(r => r.tag);
  const p = _docQParts(q);
  const facts = {
    title: _fcClip(q.title || ''),
    topic: q.topic || '',
    secondTopic: qSecondaryTopic(q),
    category: normalizeCategoryValue(q.category),
    question: _fcClip(p.text || ''),
  };
  if (p.mcq) {
    const opts = (p.mcq.options || []).map(o => stripHtml(o.text || '')).filter(Boolean);
    if (opts.length) facts.options = opts.map(o => _fcClip(o));
  }
  const model = _deriveModelAnswer(q);
  if (model) facts.modelAnswer = _fcClip(model);
  const expl = ((q.blocks || []).find(b => b && b.type === 'explanation' && stripHtml(b.content || '').trim()));
  if (expl) facts.explanation = _fcClip(expl.content);
  const already = qTagList(q);
  if (already.length) facts.tagsItAlreadyHas = already;

  const prompt = [
    'You are tagging one question in a Singapore primary-school science question bank (P3-P6).',
    '',
    'A tag names the exact idea the question TESTS, the way a teacher says it out loud: "elastic spring force", "water displacement", "shadow size", "heat conduction", "air resistance". It is finer-grained than the syllabus topic and it is not the question title.',
    '',
    'THE QUESTION:',
    JSON.stringify(facts, null, 1),
    '',
    known.length
      ? 'TAGS ALREADY IN USE IN THIS BANK. Reuse one of these, spelled EXACTLY as written here, whenever it fits the question — even loosely. Every question about one idea must carry the same string, or the tag counts split and the tag stops being useful:\n' + known.join('; ')
      : 'This bank has no tags yet, so you are setting the vocabulary. Keep the wording plain and reusable.',
    '',
    'Reply with ONLY this JSON: {"tags":["...","..."]}',
    '- Give 2 to 4 tags. Fewer is better than padding with something vague.',
    '- Prefer an existing tag over a new one every time it fits. Only invent a tag when no existing tag covers the idea, and then keep it short, lower case and plain.',
    '- Do not repeat a tag the question already has (listed as "tagsItAlreadyHas" if present) — return only tags you would ADD.',
    '- Never use the topic name on its own as a tag, never use a question number, and never use words like "PSLE", "MCQ", "open-ended", "hard" or "revision". Those describe the paper, not the science.',
    '- No punctuation, no capital letters unless it is a proper noun, no quotes inside the tag.',
  ].join('\n');

  const raw = await askGemini(prompt, { maxOutputTokens: 220, temperature: 0.15, json: true });
  const parsed = _parseAIJson(raw) || {};
  const proposed = Array.isArray(parsed.tags) ? parsed.tags
    : (typeof parsed.tags === 'string' ? parsed.tags.split(/[,\n;]+/) : []);
  const haveKeys = new Set(already.map(t => t.toLowerCase()));
  const out = [];
  qTagList({ tags: proposed }).forEach(t => {
    const snapped = _snapToKnownTag(t, known);
    const k = snapped.toLowerCase();
    if (haveKeys.has(k) || out.some(x => x.toLowerCase() === k)) return;   // already on, or already proposed
    out.push(snapped);
  });
  return out.slice(0, 4);
}

// ---- the editor's "suggest tags" button -------------------------------------
// Suggestions are APPENDED to whatever is in the box, never a replacement: the
// admin's own words are the ones that matter, and a tool that wipes them is a tool
// nobody presses twice.
async function suggestTagsForEditor(btn) {
  const input = document.getElementById('questionTags');
  if (!input) return;
  if (!blocks || !blocks.length) { showToast('Add the question first — I tag what the question says', 'info'); return; }
  const label = btn ? btn.innerHTML : '';
  if (btn) { btn.disabled = true; btn.innerHTML = '⏳ Reading…'; }
  try {
    // The question as it stands in the editor, not as it was last saved.
    const draft = {
      title: (document.getElementById('questionTitle')?.value || '').trim(),
      topic: document.getElementById('topicSelect')?.value || '',
      topic2: document.getElementById('topicSelect2')?.value || '',
      category: document.getElementById('categorySelect')?.value || '',
      blocks: JSON.parse(JSON.stringify(blocks)),
      tags: parseTagInput(input.value),
    };
    const add = await aiSuggestTags(draft);
    if (!add.length) { showToast('Nothing to add — the tags on it already cover this one', 'info'); return; }
    const merged = parseTagInput(input.value);
    add.forEach(t => { if (!merged.some(x => x.toLowerCase() === t.toLowerCase())) merged.push(t); });
    input.value = merged.join(', ');
    renderQuestionTagsUi();
    showToast('🏷 Added ' + add.length + ' tag' + (add.length === 1 ? '' : 's') + ' — edit or delete any you don\'t want', 'success');
  } catch (e) {
    console.warn('ai tag suggest', e);
    showToast('Couldn\'t suggest tags — ' + ((e && e.message) || 'try again in a moment'), 'error');
  } finally {
    if (btn) { btn.disabled = false; btn.innerHTML = label; }
  }
}

// ---- tags in the question bank ---------------------------------------------
// Chips on a bank card, each one a link to "every question with this tag". That
// click is the whole feature from the admin's side: from "this question is about
// elastic spring force" to the complete list of them, in one tap.
function qTagChipsHtml(q, opts) {
  const tags = qTagList(q);
  if (!tags.length) return '';
  const plain = !!(opts && opts.plain);
  const max = (opts && opts.max) || 4;
  const shown = tags.slice(0, max);
  const extra = tags.length - shown.length;
  const arg = t => JSON.stringify(t).replace(/"/g, '&quot;');
  let html = shown.map(t => plain
    ? '<span class="qb-tag tagged">🏷 ' + escapeHtml(t) + '</span>'
    : '<span class="qb-tag tagged" title="' + escapeHtml('Tagged “' + t + '” — click to list every question with this tag') +
      '" onclick="event.stopPropagation();bankFilterByTag(' + arg(t) + ')">🏷 ' + escapeHtml(t) + '</span>').join('');
  if (extra > 0) html += '<span class="qb-tag tagged" title="' + escapeHtml(tags.join(', ')) + '">+' + extra + '</span>';
  return html;
}

function bankFilterByTag(tag) {
  const sel = document.getElementById('bankFilterTag');
  if (!sel) return;
  const key = String(tag).toLowerCase();
  let opt = Array.from(sel.options).find(o => o.value.toLowerCase() === key);
  // The dropdown only lists tags in use, so a chip's tag is always there — but add
  // it rather than silently doing nothing if the list is mid-rebuild.
  if (!opt) { opt = document.createElement('option'); opt.value = tag; opt.textContent = '🏷 ' + tag; sel.appendChild(opt); }
  sel.value = opt.value;
  renderQuestionBank();
  showToast('🏷 Showing questions tagged “' + tag + '”', 'info');
}

// ---- bulk tagging ----------------------------------------------------------
// Tagging a bank one question at a time is a job nobody finishes. This works on a
// SET: either the questions picked in the grid, or everything the current filters
// are showing — so the real workflow is "filter to Untagged + P5 Heat, then tag all
// forty in one go".
//
// Three things can be done to that set: add tags, remove tags, or hand each
// question to the AI. Saves are per-question (the bank has no batch write) and
// sequential, with a running count and a stop button, because forty AI calls is a
// minute of someone's life and they should be able to change their mind.
const BULK_TAG_MAX = 200;          // a set larger than this is almost certainly a mis-click
const BULK_AI_CONCURRENCY = 3;     // polite to the quota, still 3× faster than serial
let _bulkTagRun = null;            // { total, done, tagged, skipped, failed, stop } while running
let _bulkTagScope = 'picked';      // 'picked' | 'shown'
let _bulkAiOnlyUntagged = true;

// Only ever write to questions THIS account owns. The bank is a union across every
// admin account for the super admin, and another admin's documents are not ours to
// write — Firestore rejects it, and one rejection per question is how a bulk pass
// turns into a wall of failures. They are counted and reported, not silently
// dropped, so a set that is mostly someone else's does not look like a bug.
function _bulkTagOwned(list) {
  const mine = [], foreign = [];
  (list || []).forEach(q => {
    if (!q || q.id == null) return;
    (_qOwner(q.id) === (currentUser && currentUser.uid) ? mine : foreign).push(q);
  });
  return { mine, foreign };
}
function _bulkTagSets() {
  const picked = _bulkTagOwned((Array.isArray(questionBank) ? questionBank : []).filter(q => q && wsSelectedIds.has(q.id)));
  const shown = _bulkTagOwned(_bankFilteredQuestions());
  return { picked: picked.mine, shown: shown.mine,
           foreign: (_bulkTagScope === 'shown' ? shown : picked).foreign.length };
}
function _bulkTagTarget() {
  const { picked, shown } = _bulkTagSets();
  const list = _bulkTagScope === 'shown' ? shown : picked;
  return list.slice(0, BULK_TAG_MAX);
}

function openBulkTags(scope) {
  if (!_canAuthor()) { showToast('Only question authors can edit tags', 'error'); return; }
  const { picked, shown } = _bulkTagSets();
  // Default to whichever set the admin actually has: their picks if they made any.
  _bulkTagScope = scope || (picked.length ? 'picked' : 'shown');
  if (!picked.length && !shown.length) { showToast('Nothing to tag — the bank is empty', 'info'); return; }
  _bulkTagRun = null;
  const ov = document.getElementById('bulkTagOverlay');
  if (ov) ov.classList.add('active');
  const add = document.getElementById('bulkTagAdd'); if (add) add.value = '';
  // "Only the untagged ones" is the right default when there IS a backlog — that is
  // the job. With nothing untagged it would offer to tag zero questions, so start
  // from the other end instead.
  _bulkAiOnlyUntagged = _bulkTagTarget().some(q => !qTagList(q).length);
  renderBulkTags();
}
function closeBulkTags() {
  // Mid-run, Done means "stop" — closing the dialog under a running pass would
  // leave it writing invisibly. Press it again once stopped to close.
  if (_bulkTagRun && !_bulkTagRun.stop) { bulkTagStop(); return; }
  const ov = document.getElementById('bulkTagOverlay');
  if (ov) ov.classList.remove('active');
  _bulkTagRun = null;
  renderQuestionBank();
}
// How many the AI would actually be given: the untagged ones when that box is
// ticked AND there are any, otherwise the whole set.
function _fcAiTargetCount(n, untagged) { return (_bulkAiOnlyUntagged && untagged) ? untagged : n; }
function bulkTagScope(scope) {
  _bulkTagScope = scope === 'shown' ? 'shown' : 'picked';
  _bulkAiOnlyUntagged = _bulkTagTarget().some(q => !qTagList(q).length);   // the new set may have no backlog
  renderBulkTags();
}
function bulkTagAiScope(onlyUntagged) { _bulkAiOnlyUntagged = !!onlyUntagged; renderBulkTags(); }

function renderBulkTags() {
  const body = document.getElementById('bulkTagBody');
  if (!body) return;
  const { picked, shown, foreign } = _bulkTagSets();
  const target = _bulkTagTarget();
  const n = target.length;
  const untagged = target.filter(q => !qTagList(q).length).length;
  const run = _bulkTagRun;

  // Tags present across the target set — the only ones worth offering to remove.
  const onSet = allBankTags(target);
  const reuse = allBankTags().filter(r => r.n > 0).slice(0, 18);

  const scopeBtn = (key, label, count, note) => `
    <button type="button" class="bt-scope${_bulkTagScope === key ? ' on' : ''}" ${count ? '' : 'disabled'} onclick="bulkTagScope('${key}')">
      <b>${count} question${count === 1 ? '' : 's'}</b>
      <span>${escapeHtml(label)}</span>
      ${note ? `<span class="bt-scope-note">${escapeHtml(note)}</span>` : ''}
    </button>`;

  if (run) {
    const pct = run.total ? Math.round(100 * run.done / run.total) : 0;
    body.innerHTML = `
      <div class="bt-run">
        <div class="bt-run-title">${run.stop ? 'Stopping…' : (run.kind === 'ai' ? '✨ Tagging with AI' : 'Applying your tags')}</div>
        <div class="fc-bar" style="margin-top:14px;"><div class="fc-bar-fill" style="width:${pct}%;"></div></div>
        <div class="bt-run-line">${run.done} of ${run.total} done · ${run.tagged} changed${run.skipped ? ' · ' + run.skipped + ' left alone' : ''}${run.failed ? ' · ' + run.failed + ' failed' : ''}</div>
        <div class="bt-run-note">Every question is saved as it finishes, so stopping keeps everything done so far.</div>
        <div class="bt-actions">
          <button class="btn btn-outline" onclick="bulkTagStop()" ${run.stop ? 'disabled' : ''}>${run.stop ? 'Stopping…' : 'Stop'}</button>
        </div>
      </div>`;
    return;
  }

  body.innerHTML = `
    <div class="bt-scopes">
      ${scopeBtn('picked', 'you picked in the grid', picked.length, picked.length ? '' : 'Click tiles in grid view to pick')}
      ${scopeBtn('shown', 'shown by your filters', shown.length, shown.length > BULK_TAG_MAX ? 'Capped at ' + BULK_TAG_MAX : '')}
    </div>
    <div class="bt-target">Working on <b>${n}</b> question${n === 1 ? '' : 's'}${untagged ? ` · ${untagged} of them have no tags yet` : (n ? ' · all of them already have tags' : '')}.${
      foreign ? ` <span style="color:var(--accent-orange);">${foreign} more belong to another teacher's account, so they're left out.</span>` : ''}</div>

    <div class="bt-section">
      <div class="bt-h">✨ Let the AI tag them</div>
      <p class="bt-p">Each question is read on its own and tagged from the vocabulary you've already built — an existing tag is reused wherever it fits, and a new one only invented when nothing covers the idea. Suggestions are <b>added</b>; nothing you've written is removed.</p>
      ${untagged ? `<label class="bt-check"><input type="checkbox" ${_bulkAiOnlyUntagged ? 'checked' : ''} onchange="bulkTagAiScope(this.checked)"> Only the ${untagged} question${untagged === 1 ? '' : 's'} with no tags yet <span>— untick to top up ones that already have some</span></label>`
        : `<div class="bt-p" style="margin:0;">Everything in this set already has tags, so the AI will look for ones to <b>add</b> to each.</div>`}
      <div class="bt-actions">
        <button class="btn btn-primary" onclick="bulkTagAiRun()" ${_fcAiTargetCount(n, untagged) ? '' : 'disabled'}>
          ✨ Tag ${_fcAiTargetCount(n, untagged)} question${_fcAiTargetCount(n, untagged) === 1 ? '' : 's'} with AI
        </button>
      </div>
    </div>

    <div class="bt-section">
      <div class="bt-h">🏷 Add the same tags to all of them</div>
      <p class="bt-p">Comma-separated. Anything a question already has is left alone, so this is safe to run twice. If you spell a tag differently from one the bank already uses, it's filed under the existing spelling — that's what keeps the counts together.</p>
      <input id="bulkTagAdd" class="form-input" type="text" autocomplete="off" spellcheck="false" placeholder="elastic spring force, extension of spring" oninput="renderBulkTagsPreview()">
      <div id="bulkTagAddPreview" class="qtag-row" style="display:none;"></div>
      ${reuse.length ? `<div class="qtag-reuse" style="margin-top:13px;">
        <div class="qtag-reuse-label">Tags in use — tap to add</div>
        <div class="qtag-row">${reuse.map(r => `<button type="button" class="qtag-pick" onclick="bulkTagAddPick(${JSON.stringify(r.tag).replace(/"/g, '&quot;')})">${escapeHtml(r.tag)}<b>${r.n}</b></button>`).join('')}</div>
      </div>` : ''}
      <div class="bt-actions">
        <button class="btn btn-primary" onclick="bulkTagApply('add')">Add to all ${n}</button>
      </div>
    </div>

    ${onSet.length ? `
    <div class="bt-section">
      <div class="bt-h">🧹 Take a tag off all of them</div>
      <p class="bt-p">Only tags that actually appear in this set are listed, with how many of them carry it.</p>
      <div class="qtag-row">
        ${onSet.map(r => `<button type="button" class="qtag-pick" onclick="bulkTagRemove(${JSON.stringify(r.tag).replace(/"/g, '&quot;')})" title="Remove “${escapeHtml(r.tag)}” from the ${r.n} question${r.n === 1 ? '' : 's'} in this set that have it">✕ ${escapeHtml(r.tag)}<b>${r.n}</b></button>`).join('')}
      </div>
    </div>` : ''}`;
  renderBulkTagsPreview();
}

function renderBulkTagsPreview() {
  const input = document.getElementById('bulkTagAdd');
  const prev = document.getElementById('bulkTagAddPreview');
  if (!input || !prev) return;
  const tags = parseTagInput(input.value);
  if (!tags.length) { prev.style.display = 'none'; prev.innerHTML = ''; return; }
  const counts = new Map(allBankTags().map(r => [r.key, r.n]));
  prev.style.display = 'flex';
  prev.innerHTML = tags.map(t => {
    const c = counts.get(t.toLowerCase()) || 0;
    return `<span class="qtag-chip${c ? '' : ' fresh'}" title="${escapeHtml(c ? c + ' question(s) in the bank already carry this tag' : 'A new tag — nothing else uses it yet')}">${escapeHtml(t)}<b>${c || 'new'}</b></span>`;
  }).join('');
}
function bulkTagAddPick(tag) {
  const input = document.getElementById('bulkTagAdd');
  if (!input) return;
  const list = parseTagInput(input.value);
  if (!list.some(t => t.toLowerCase() === String(tag).toLowerCase())) list.push(tag);
  input.value = list.join(', ');
  renderBulkTagsPreview();
  input.focus();
}

// Write one question's tags and keep every in-memory copy in step.
async function _bulkTagWrite(q, tags) {
  // Tag passes hold references across awaits. The editor's save REPLACES the
  // bank slot with a rebuilt object (and a delete removes it), so a held
  // reference that is no longer the live object must not be written — setDoc
  // overwrites the whole doc, and writing the stale object would resurrect the
  // pre-edit (or deleted) question.
  const live = (Array.isArray(questionBank) ? questionBank : []).find(x => x && x.id === q.id);
  if (live !== q) return false;
  const prev = q.tags;
  q.tags = tags;
  const ok = await saveQuestion(q, { quiet: true });
  if (!ok) q.tags = prev;   // a write that never landed must not tag the in-memory copy
  return ok;
}

// Add or remove a fixed set of tags across the target. Sequential and per-question
// so a permission failure on one row cannot roll back the rest.
async function bulkTagApply(action, oneTag) {
  const target = _bulkTagTarget();
  if (!target.length) { showToast('Nothing selected', 'info'); return; }
  // Removal matches case-insensitively, so it must NOT be snapped — snapping
  // "Heat Conduction" to "heat conduction" would be a no-op there anyway, but on a
  // set where only the odd spelling exists it would quietly miss.
  const tags = action === 'remove'
    ? parseTagInput(oneTag || '')
    : _snapTagsToBank(parseTagInput((document.getElementById('bulkTagAdd')?.value) || ''));
  if (!tags.length) { showToast(action === 'remove' ? 'Nothing to remove' : 'Type a tag first', 'info'); return; }
  const keys = new Set(tags.map(t => t.toLowerCase()));
  if (action === 'remove' && !confirm('Remove ' + tags.map(t => '“' + t + '”').join(', ') + ' from every question in this set that has it?\n\nThis cannot be undone.')) return;

  autoTagStop();   // the admin's own pass takes priority over the background one
  // Hold a LOCAL reference: closing the dialog nulls the global mid-flight, and
  // the loop resuming from an await must not dereference null.
  const run = _bulkTagRun = { kind: 'manual', total: target.length, done: 0, tagged: 0, skipped: 0, failed: 0, stop: false };
  renderBulkTags();
  for (const q of target) {
    if (run.stop) break;
    const before = qTagList(q);
    let after;
    if (action === 'remove') after = before.filter(t => !keys.has(t.toLowerCase()));
    else {
      after = before.slice();
      tags.forEach(t => { if (!after.some(x => x.toLowerCase() === t.toLowerCase())) after.push(t); });
    }
    if (after.length === before.length && after.every((t, i) => t === before[i])) run.skipped++;
    else if (await _bulkTagWrite(q, after)) run.tagged++;
    else run.failed++;
    run.done++;
    renderBulkTags();
  }
  _bulkTagFinish(action === 'remove' ? 'removed from' : 'added to');
}

// One AI call per question, a few in flight at a time.
async function bulkTagAiRun() {
  let target = _bulkTagTarget();
  const untagged = target.filter(q => !qTagList(q).length);
  if (_bulkAiOnlyUntagged && untagged.length) target = untagged;
  if (!target.length) { showToast('Nothing to tag in this set', 'info'); return; }
  if (!window.__aiReady || !window.__aiReady()) { showToast('AI is not ready yet — try again in a moment', 'info'); return; }
  if (!confirm('Tag ' + target.length + ' question' + (target.length === 1 ? '' : 's') + ' with AI?\n\n'
    + 'That is ' + target.length + ' AI call' + (target.length === 1 ? '' : 's') + '. Tags are ADDED, never removed, and you can stop at any point — everything done so far is kept.')) return;

  autoTagStop();   // the admin's own pass takes priority over the background one
  // Same LOCAL reference rule as bulkTagApply: workers resuming from an await
  // must never dereference the nulled global after the dialog closes.
  const run = _bulkTagRun = { kind: 'ai', total: target.length, done: 0, tagged: 0, skipped: 0, failed: 0, stop: false };
  renderBulkTags();
  let next = 0;
  const worker = async () => {
    while (!run.stop && next < target.length) {
      const q = target[next++];
      try {
        const add = await aiSuggestTags(q);
        if (!add.length) run.skipped++;
        else {
          const merged = qTagList(q);
          add.forEach(t => { if (!merged.some(x => x.toLowerCase() === t.toLowerCase())) merged.push(t); });
          if (await _bulkTagWrite(q, merged)) run.tagged++; else run.failed++;
        }
      } catch (e) {
        console.warn('bulk ai tag', (q && q.id), e);
        run.failed++;
      }
      run.done++;
      renderBulkTags();
    }
  };
  await Promise.all(Array.from({ length: Math.min(BULK_AI_CONCURRENCY, target.length) }, worker));
  _bulkTagFinish('tagged');
}

function bulkTagStop() { if (_bulkTagRun) { _bulkTagRun.stop = true; renderBulkTags(); } }

function _bulkTagFinish(verb) {
  const r = _bulkTagRun || { tagged: 0, skipped: 0, failed: 0, stop: false };
  _bulkTagRun = null;
  _ainsteinTextCache.clear();          // tags feed Ai-nstein's retrieval
  populateTagFilter();
  renderQuestionBank();
  renderBulkTags();
  const bits = [r.tagged + ' question' + (r.tagged === 1 ? '' : 's') + ' ' + verb];
  if (r.skipped) bits.push(r.skipped + ' left alone');
  if (r.failed) bits.push(r.failed + ' failed');
  showToast((r.stop ? 'Stopped — ' : '🏷 ') + bits.join(' · '), r.failed ? 'error' : 'success');
}

function bulkTagRemove(tag) { bulkTagApply('remove', tag); }

// ---- automatic whole-bank tagging -------------------------------------------
// "Every question carries at least one tag" as a standing guarantee, not a chore
// someone has to remember. After the bank loads for an admin, every owned
// question with no tags is handed to the AI in the background — ten workers in
// flight at once, each reading and tagging one question at a time. A question
// the AI reads but has nothing to say about still gets ONE tag from its own
// metadata (topic, then category), so a successfully processed question never
// stays untagged; a question whose CALL failed is left alone to retry later
// (see _autoTagOne for why those must not get the floor). Saves are
// per-question, so closing the tab mid-pass keeps everything already done;
// whatever is left picks up at the next sign-in.
const AUTO_TAG_WORKERS = 10;        // tagging workers in flight at once
const AUTO_TAG_MAX = 500;           // per pass — a bigger backlog continues at the next sign-in
let _autoTagRun = null;             // { total, done, tagged, failed, stop } while running
let _autoTagRanThisLoad = false;    // once per page load — tagged questions no longer target anyway

// The guaranteed floor: a tag from the question's own metadata. The AI prompt
// forbids the bare topic as a tag, but as a floor it beats untagged — the
// question still files under a label the admin recognises, and the next AI pass
// is free to add finer ones on top. Each candidate is pushed through the tag
// parser BEFORE being chosen, because a candidate can be truthy yet parse to
// nothing (a purely numeric topic like "2025" is dropped by qTagList) — picking
// on truthiness alone would skip the candidates behind it and break the floor.
function _autoTagFallbackTags(q) {
  const candidates = [String((q && q.topic) || '').trim(), qSecondaryTopic(q),
                      normalizeCategoryValue(q && q.category), 'general science'];
  for (const c of candidates) {
    const tags = _snapTagsToBank(parseTagInput(c));
    if (tags.length) return tags;
  }
  return ['general science'];
}

// Returns 'tagged' or 'failed'. A FAILED call writes nothing: the question stays
// untagged, so the next sign-in retries it with a real AI call. Only a genuine
// empty reply gets the metadata floor — "the AI had nothing to say" is an answer,
// a quota blip is not, and stamping the topic name on a question just because a
// call bounced would permanently seal it against ever being properly tagged.
async function _autoTagOne(q) {
  let add;
  try { add = await aiSuggestTags(q); }
  catch (e) { console.warn('auto tag', q && q.id, e); return 'failed'; }
  if (!add.length) add = _autoTagFallbackTags(q);
  const merged = qTagList(q);
  add.forEach(t => { if (!merged.some(x => x.toLowerCase() === t.toLowerCase())) merged.push(t); });
  return (await _bulkTagWrite(q, merged)) ? 'tagged' : 'failed';
}

async function autoTagAllQuestions() {
  if (!_isAdmin() || _autoTagRun) return;
  // Only questions THIS account owns — another admin's documents are not ours
  // to write, and Firestore would reject every one (see _bulkTagOwned). Each
  // admin's own sign-in tags their own bank.
  const backlog = (Array.isArray(questionBank) ? questionBank : [])
    .filter(q => q && q.id != null && !qTagList(q).length &&
                 _qOwner(q.id) === (currentUser && currentUser.uid));
  const target = backlog.slice(0, AUTO_TAG_MAX);
  if (!target.length) return;
  // Workers hold this LOCAL reference, not the global — nothing outside can null
  // it out from under an in-flight await.
  const run = _autoTagRun = { total: target.length, done: 0, tagged: 0, failed: 0, stop: false };
  showToast('🏷 Auto-tagging ' + target.length + ' untagged question' + (target.length === 1 ? '' : 's') +
    (backlog.length > target.length ? ' (of ' + backlog.length + ' — the rest at the next sign-in)' : '') +
    ' in the background…', 'info');
  let next = 0;
  const worker = async () => {
    while (!run.stop && next < target.length) {
      const q = target[next++];
      try {
        // A manual bulk pass or the editor may have tagged — or deleted — this
        // question since the target was captured: no AI call for those.
        if (qTagList(q).length || questionBank.indexOf(q) === -1) { run.done++; continue; }
        run[await _autoTagOne(q)]++;
      } catch (e) { console.warn('auto tag worker', q && q.id, e); run.failed++; }
      run.done++;
    }
  };
  try {
    await Promise.all(Array.from({ length: Math.min(AUTO_TAG_WORKERS, target.length) }, worker));
  } finally {
    _autoTagRun = null;                // never leave the guard latched
  }
  _ainsteinTextCache.clear();          // tags feed Ai-nstein's retrieval
  renderQuestionBank();                // rebuilds the tag filter too, behind its focus guard
  if (run.stop) return;                // yielded to a manual pass — its own toast takes over
  showToast('🏷 Auto-tagged ' + run.tagged + ' question' + (run.tagged === 1 ? '' : 's') +
    (run.failed ? ' · ' + run.failed + ' failed — those stay untagged and retry at the next sign-in' : ''),
    run.failed ? 'error' : 'success');
}

// Stop the background pass: from the console, or because the admin started a
// manual bulk pass of their own — two passes writing the same rows at once is
// wasted AI spend and a write race for no benefit.
function autoTagStop() { if (_autoTagRun) _autoTagRun.stop = true; }

// Kick the pass off without holding up sign-in: give the page a moment to
// settle, wait (briefly) for the AI to come up, then run.
function autoTagWholeBankInBackground() {
  if (_autoTagRanThisLoad || !_isAdmin()) return;
  _autoTagRanThisLoad = true;
  let waited = 0;
  const tick = () => {
    if (window.__aiReady && window.__aiReady()) { autoTagAllQuestions().catch(e => console.warn('auto tag pass', e)); return; }
    // The AI never came up: re-arm, so a sign-out/sign-in in this same tab gets
    // another go instead of finding the latch stuck for the rest of the load.
    if ((waited += 1000) >= 30000) { _autoTagRanThisLoad = false; return; }
    setTimeout(tick, 1000);
  };
  setTimeout(tick, 3000);
}

// Rebuilt on every bank render, so a tag added a moment ago is selectable now.
// "Untagged" is a real filter, not an oversight: it is the list an admin works
// through when they decide to start tagging.
function populateTagFilter() {
  const sel = document.getElementById('bankFilterTag');
  if (!sel) return;
  const prev = sel.value;
  const rows = allBankTags();
  const untagged = (Array.isArray(questionBank) ? questionBank : []).filter(q => !qTagList(q).length).length;
  sel.innerHTML = '<option value="">All tags</option>' +
    rows.map(r => '<option value="' + escapeHtml(r.tag) + '">🏷 ' + escapeHtml(r.tag) + ' (' + r.n + ')</option>').join('') +
    (untagged ? '<option value="__none__">— Untagged (' + untagged + ') —</option>' : '');
  sel.value = Array.from(sel.options).some(o => o.value === prev) ? prev : '';
}
// Extra tag(s) for a question's 2nd category / 2nd topic — empty string when none.
function qSecondaryTagsHtml(q) {
  const c2 = qSecondaryCategory(q);
  const t2 = qSecondaryTopic(q);
  let html = '';
  if (c2 && c2 !== normalizeCategoryValue(q && q.category)) html += `<span class="qb-tag category alt" title="2nd category">${escapeHtml(c2)}</span>`;
  if (t2 && t2 !== (((q && q.topic) || '').trim())) html += `<span class="qb-tag topic alt" title="2nd topic">${escapeHtml(t2)}</span>`;
  return html;
}

// Every question that contains a multiple-choice block is categorised under the
// "Multiple Choice Question" category, regardless of any other category picked —
// EXCEPT when the author deliberately filed it under a PSLE category, which we
// keep as chosen (PSLE - MCQ questions legitimately contain MCQ blocks).
const MCQ_CATEGORY = 'Multiple Choice Question';
const PSLE_CATEGORIES = new Set(['PSLE - MCQ', 'PSLE - OEQ']);
function applyMcqCategory(q) {
  // Deliberate PSLE or admin-defined custom categories are kept as chosen.
  if (q && qpHasMcq(q) && !(q.category && (PSLE_CATEGORIES.has(q.category) || isCustomCategory(q.category)))) q.category = MCQ_CATEGORY;
  return q;
}

// =====================================================================
// NAVIGATION
// =====================================================================
function navigateTo(page) {
  // Employees may only reach the pages they were hired to use. Hiding the nav
  // items is not enough on its own — a bookmark, a deep link (#usage) or any
  // navigateTo() call from shared code would otherwise walk straight in.
  if (_isEmployee() && EMPLOYEE_PAGES.indexOf(page) < 0) page = 'create';
  // Science Quest game pages: respect the "Hide game" toggle, and leaving
  // the dungeon abandons the current run (rewards are kept).
  if ((page === 'character' || page === 'leaderboard' || page === 'adventure' || page === 'arcade' || page === 'defenders' || page === 'raiders' || page === 'spire' || page === 'legends' || page === 'slayers' || page === 'tcg') && rpgGameHidden()) page = rpgHomePage();
  // Realm of Embers TCG is admin-only until the admin presses Release.
  if (page === 'tcg' && !_isAdmin() && !tcgReleased()) page = rpgHomePage();
  if (page !== 'adventure') advAbandon();
  // Snap & Mark keeps marking in the background — reassure the student on leave.
  try {
    const smPage = document.getElementById('page-snapmark');
    if (page !== 'snapmark' && smPage && smPage.classList.contains('active') && _snapRun && _snapRun.active) {
      showToast('📸 Still marking in the background — we\'ll let you know when your report is ready', 'info');
    }
  } catch (e) {}
  document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
  document.querySelectorAll('.nav-item').forEach(n => n.classList.remove('active'));
  document.getElementById('page-' + page).classList.add('active');
  // 🔥 Realm of Embers takes the whole app with it: stepping into the realm
  // swaps the portal's white theme for the gold-on-galaxy one, and stepping
  // out puts it back. One class on <body>; everything else is CSS, which is
  // what keeps the swap instant and impossible to leave half-applied.
  document.body.classList.toggle('realm-embers', page === 'tcg');
  if (page !== 'tcg') { try { tcgLoreClose(); } catch (_) {} }
  // The five games live inside the Arcade — highlight its nav item for them.
  const navItem = document.querySelector(`.nav-item[data-page="${page}"]`) ||
    (['defenders', 'raiders', 'spire', 'legends', 'slayers'].includes(page) ? document.querySelector('.nav-item[data-page="arcade"]') : null);
  if (navItem) navItem.classList.add('active');
  try { _navBmSyncActive(); } catch (_) {}   // the mirrored copy lights up too
  // Close sidebar on mobile after navigation
  const sidebar = document.getElementById('sidebar');
  const backdrop = document.getElementById('sidebarBackdrop');
  if (sidebar) sidebar.classList.remove('open');
  if (backdrop) backdrop.style.display = 'none';
  ensureMobileToggles();
  if (page === 'create') {
    dupWatchBind();          // idempotent; the listener outlives every reset
    if (_skipCreateReset) {
      // Coming from editQuestion — switch to edit mode
      setEditMode(!!currentEditingQuestion);
    } else {
      // Fresh create — reset everything
      blocks = [];
      selectedBlanks = {};
      currentEditingQuestion = null;
      _editReturnPage = null;           // a brand-new question won't return to Past Papers
      _hideDupBanner();
      document.getElementById('questionTitle').value = '';
      document.getElementById('categorySelect').value = 'CER';
      document.getElementById('topicSelect').value = 'Heat';
      const cs2 = document.getElementById('categorySelect2'); if (cs2) cs2.value = '';
      const ts2 = document.getElementById('topicSelect2'); if (ts2) ts2.value = '';
  if (typeof _setAnswerKeyFields === 'function') _setAnswerKeyFields('', '');
      const annEl = document.getElementById('questionAnnotation');
      if (annEl) annEl.checked = false;
      const nisEl = document.getElementById('questionNotInSyllabus');
      if (nisEl) nisEl.checked = false;
      if (typeof setQuestionTagsField === 'function') setQuestionTagsField(null);
      if (typeof loEditorSet === 'function') loEditorSet([]);
      renderBlocks();
      setEditMode(false);
      if (window.ppCancelPendingAttach) window.ppCancelPendingAttach();
    }
  } else {
    // Leaving the create page drops any pending past-paper attachment
    if (window.ppCancelPendingAttach) window.ppCancelPendingAttach();
  }
  _skipCreateReset = false;
  if (page === 'bank') renderQuestionBank();
  if (page === 'answerkeys') renderAnswerKeysPage();
  if (page === 'ansreview') renderAnswerReview();
  if (page === 'papers') renderPapersPage();
  if (page === 'notes') renderNotesPage();
  if (page === 'vetting') renderVettingList();
  if (page === 'checkq') renderCheckQPage();
  if (page === 'student') {
    populateStudentSelect();
    renderStudentView();
  }
  if (page === 'print') {
    renderPrintSelect();
    // Position toolbar below the sticky page-header
    requestAnimationFrame(() => {
      const hdr = document.getElementById('printPageHeader');
      const tb = document.getElementById('printToolbar');
      if (hdr && tb) tb.style.top = hdr.offsetHeight + 'px';
    });
  }
  if (page === 'practice') populatePracticeStudentSelect();
  if (page === 'worksheet') {
    populateWsTopicFilter();
    renderWsQuestions();
  }
  if (page === 'myworksheets') renderSavedWorksheets();
  if (page === 'worksession') { wkRenderPage(); wkLoadHistory(); }
  if (page === 'exampaper') {
    _epBindPaste();
    epRender();
    // Looks for this tab's own unsent paper (a reload) and for any left behind
    // by a window that is no longer open. Runs once per sign-in.
    if (!_epDraftReady) _epDraftScan().catch(err => console.warn('exam paper drafts:', err));
  }
  if (page === 'markpaper') { _mpBindPaste(); mpRender(); }
  if (page === 'quickpractice') { populateQpControls(); updateQpProgress(); }
  if (page === 'snapmark') snapInit();
  if (page === 'topicalpractice') tpRenderTopics();
  if (page === 'community') renderCommunity();
  if (page === 'usage') loadUsageDashboard();
  if (page === 'myreport') loadMyReport();
  if (page === 'flashcards') renderFlashcardsPage();
  if (page === 'familysettings') famRenderSettings();
  if (page === 'scheduled') loadScheduledQuestions();
  if (page === 'flagged') loadFlaggedQuestions();
  if (page === 'doctor') renderDoctorPage();
  if (page === 'character') rpgRenderCharacterPage();
  if (page === 'leaderboard') rpgRenderLeaderboard();
  if (page === 'adventure') rpgRenderAdventure();
  if (page === 'practice' || page === 'quickpractice' || page === 'topicalpractice') rpgRenderBattle();
  if (page === 'objectives') renderObjectivesPage();
  if (page === 'textbooks') {
    const f = document.getElementById('textbooksFrame');
    if (f && !f.getAttribute('src')) f.setAttribute('src', 'textbooks.html');   // load once, on first visit
  }
  if (page === 'defenders') {
    const f = document.getElementById('defendersFrame');
    if (f && !f.getAttribute('src')) f.setAttribute('src', 'science-defenders.html');
  }
  if (page === 'raiders') {
    const f = document.getElementById('raidersFrame');
    if (f && !f.getAttribute('src')) { f.setAttribute('src', 'science-raiders.html'); f.addEventListener('load', pushRaidersAssets); }
    else pushRaidersAssets();
  }
  if (page === 'spire') {
    const f = document.getElementById('spireFrame');
    if (f && !f.getAttribute('src')) { f.setAttribute('src', 'science-spire.html'); f.addEventListener('load', pushSpireAssets); }
    else pushSpireAssets();
  }
  if (page === 'legends') {
    const f = document.getElementById('legendsFrame');
    if (f && !f.getAttribute('src')) { f.setAttribute('src', 'science-legends.html'); f.addEventListener('load', pushLegendsAssets); }
    else pushLegendsAssets();
  }
  if (page === 'slayers') {
    const f = document.getElementById('slayersFrame');
    if (f && !f.getAttribute('src')) { f.setAttribute('src', 'science-slayers.html'); f.addEventListener('load', pushLegendsAssets); }
    else pushLegendsAssets();
  }
  if (page === 'gameassets') loadGameAssets();
  if (page === 'tcg') tcgRenderPage();
  if (page === 'messages') loadMessagesPage();
  if (page === 'home') renderHomePage();
  if (page === 'arcade') renderArcadePage();
  // close sidebar on mobile
  document.getElementById('sidebar').classList.remove('open');
}

function toggleSidebar() {
  // Desktop: collapse/expand the fixed sidebar so the content area can use the full width
  if (window.innerWidth > 768) {
    const collapsed = document.body.classList.toggle('sidebar-collapsed');
    try { localStorage.setItem('sidebarCollapsed', collapsed ? '1' : '0'); } catch (e) {}
    return;
  }
  const sidebar = document.getElementById('sidebar');
  const backdrop = document.getElementById('sidebarBackdrop');
  sidebar.classList.toggle('open');
  if (backdrop) {
    backdrop.style.display = sidebar.classList.contains('open') ? 'block' : 'none';
  }
}

// Restore the collapsed state from the last visit (desktop only; harmless on mobile
// where the drawer CSS takes over)
try {
  if (localStorage.getItem('sidebarCollapsed') === '1') document.body.classList.add('sidebar-collapsed');
} catch (e) {}

// Safety net: every page header must offer a way to open the sidebar on
// mobile. Injects the hamburger into any .page-header that lacks one
// (runs at startup and on every navigation, so dynamically rendered
// headers are covered too).
function ensureMobileToggles() {
  document.querySelectorAll('.page-header').forEach((hdr) => {
    if (hdr.querySelector('.mobile-toggle')) return;
    const btn = document.createElement('button');
    btn.className = 'mobile-toggle';
    btn.setAttribute('aria-label', 'Open menu');
    btn.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 12h18M3 6h18M3 18h18"/></svg>';
    btn.addEventListener('click', toggleSidebar);
    hdr.insertBefore(btn, hdr.firstChild);
  });
}

