// ---- State & storage ----
let rpgState = null;
let rpgHintUsedQ = false;   // hint used on the current question → reduced battle damage
let rpgCharTab = "inventory";
let rpgShopSlot = "all";

function rpgStorageKey() { return "scienceQuestRpg:" + (currentUser ? currentUser.uid : "anon"); }
function rpgDefaults() {
  return {
    v: 2, gold: 60, xp: 0, hp: null, hidden: false, battleMin: false, gender: null,
    monthKey: null, monthXp: 0, lastMonthKey: null, lastMonthXp: 0, advRuns: null, dungeonFloor: 1,
    monthQ: 0, lastMonthQ: 0, monthQids: {}, monthPrints: {}, prizeAck: {},
    duelQ: 0, duelCorrect: 0,          // 🎴 Ember Duel board: questions done and got right
    gameScores: { defenders: { best: 0, bestLabel: "", monthBest: 0, monthLabel: "", monthKey: null, lastBest: 0, lastLabel: "", lastKey: null },
                  raiders:   { best: 0, bestLabel: "", monthBest: 0, monthLabel: "", monthKey: null, lastBest: 0, lastLabel: "", lastKey: null } },
    inventory: { wood_sword: 1, cloth_tunic: 1 },
    equipment: { weapon: "wood_sword", shield: null, armor: "cloth_tunic", helmet: null, accessory: null, pet: null },
    spireCards: {}, spireDeck: [],
    battle: null, upgrades: {}, clazz: null, skills: {}, paths: {}, affixes: {}, petBond: {}, daily: null, streak: null, packCoupon: 0, rebirths: 0, xpBaseline: 0, shards: 0, star: { gold: 0, learn: 0, raids: 0, nova: false }, kills: {}, seenQ: {},
    stats: { wins: 0, defeats: 0, marked: 0, correct: 0, goldEarned: 0 }
  };
}
function rpgReadLocal() {
  try { return JSON.parse(localStorage.getItem(rpgStorageKey()) || "null"); } catch (e) { return null; }
}
function rpgWriteLocal() {
  try { localStorage.setItem(rpgStorageKey(), JSON.stringify(rpgState)); } catch (_) {}
}
async function rpgLoadState() {
  if (RPG_STORAGE_MODE === "firestore") {
    // NOTE: let read errors propagate to the caller. We must NOT silently fall
    // back to (possibly empty/stale) local data here — rpgInit saves right after
    // loading, so a swallowed network error would overwrite the good cloud save
    // with blank/old data (lost upgrades, rebirths, levels). Only fall back to
    // local when the cloud genuinely has no document yet (first-time migration).
    const snap = await getDoc(doc(db, "users", currentUser.uid, "settings", "scienceRpg"));
    if (snap.exists()) return snap.data();
    return rpgReadLocal(); // one-time migration from a local preview
  }
  return rpgReadLocal();
}
function rpgHydrate(saved) {
  const st = Object.assign(rpgDefaults(), saved || {});
  st.inventory = Object.assign({}, (saved && saved.inventory) || rpgDefaults().inventory);
  st.equipment = Object.assign(rpgDefaults().equipment, (saved && saved.equipment) || {});
  st.spireCards = Object.assign({}, (saved && saved.spireCards) || {});
  st.spireDeck = Array.isArray(saved && saved.spireDeck) ? saved.spireDeck.slice(0, 60) : [];
  st.stats = Object.assign(rpgDefaults().stats, (saved && saved.stats) || {});
  // creditSum (the fractional marks total) only started counting in v1.231.0,
  // while `marked` / `correct` go back to the start of the hero. An honestly
  // accumulated creditSum can never sit below 0.95 × correct — every question
  // in that count scored at least 0.95 — so anything lower is history the
  // counter never saw, and it is seeded from the binary count once. Without
  // this every question a student answered before that date reads as WRONG
  // for the rest of their life on the All-Time board.
  {
    const sc = Number(st.stats.creditSum) || 0, sb = st.stats.correct | 0;
    if (sc < sb * 0.95) st.stats.creditSum = Math.min(st.stats.marked | 0, sb);
  }
  st.upgrades = Object.assign({}, (saved && saved.upgrades) || {});
  st.skills = Object.assign({}, (saved && saved.skills) || {});
  st.paths = Object.assign({}, (saved && saved.paths) || {});
  st.affixes = Object.assign({}, (saved && saved.affixes) || {});
  st.petBond = Object.assign({}, (saved && saved.petBond) || {});
  st.star = Object.assign({ gold: 0, learn: 0, raids: 0, nova: false }, (saved && saved.star) || {});
  st.kills = Object.assign({}, (saved && saved.kills) || {});
  st.seenQ = Object.assign({}, (saved && saved.seenQ) || {});
  st.tcg = tcgHydrateState(saved && saved.tcg); // Realm of Embers TCG collection/team/record
  if (!Number.isFinite(st.xpBaseline)) st.xpBaseline = 0;
  if ((saved && saved.v || 1) < 2) { st.skills = {}; st.paths = {}; st.v = 2; } // tree rework: full free refund
  Object.keys(st.skills).forEach(id => {
    const n = RPG_TREE_BY_ID[id];
    if (!n) delete st.skills[id];
    else st.skills[id] = Math.min(st.skills[id], n.max);
  });
  if (st.clazz && !["warrior", "rogue", "mage"].includes(st.clazz)) st.clazz = null;
  if (st.clazz && st.equipment.weapon) {
    const w = RPG_ITEMS_BY_ID[st.equipment.weapon];
    const kind = w ? rpgWeaponFx(w.id).kind : "";
    if (w && ((st.clazz === "warrior" && (kind === "ranged" || kind === "magic")) || (st.clazz === "mage" && kind !== "magic" && kind !== "ranged"))) st.equipment.weapon = null;
  }
  RPG_SLOTS.forEach(slot => {
    const it = RPG_ITEMS_BY_ID[st.equipment[slot]];
    if (!it || it.slot !== slot || !st.inventory[it.id]) st.equipment[slot] = null;
  });
  if (st.battle && !RPG_ENEMIES_BY_ID[st.battle.enemyId]) st.battle = null;
  if (!Number.isFinite(st.gold)) st.gold = 0;
  if (!Number.isFinite(st.xp)) st.xp = 0;
  if (!Number.isFinite(st.monthXp)) st.monthXp = 0;
  if (!st.cap99Fix) {
    // one-time rebalance: heroes parked at the level cap without a rebirth are
    // set back to level 60, the Starfall threshold, so prestige is the next step
    st.cap99Fix = true;
    let lvl = 1, rem = Math.max(0, st.xp - (st.xpBaseline || 0));
    while (lvl < 99 && rem >= rpgXpToNext(lvl)) { rem -= rpgXpToNext(lvl); lvl++; }
    if (lvl >= 99 && !(st.rebirths > 0)) {
      let need = 0;
      for (let l = 1; l < 60; l++) need += rpgXpToNext(l);
      st.xp = (st.xpBaseline || 0) + need;
      const spent = Object.values(st.skills).reduce((a, b) => a + b, 0);
      if (spent > 45) { st.skills = {}; if (st.clazz) delete st.paths[st.clazz]; } // over level-60 budget: free refund
    }
  }
  return st;
}
function rpgSave() {
  if (!rpgState || !currentUser) return;
  rpgState.updatedAt = new Date().toISOString();
  if (RPG_STORAGE_MODE === "firestore") {
    setDoc(doc(db, "users", currentUser.uid, "settings", "scienceRpg"), rpgState)
      .catch(e => { console.warn("rpg save", e); rpgWriteLocal(); });
  } else {
    rpgWriteLocal();
  }
  rpgRenderSide();
}
function rpgSetGender(g) {
  if (!rpgState) return;
  rpgState.gender = (g === "male" || g === "female") ? g : null;
  rpgSave();
  rpgRenderCharacterPage();
  try { rpgRenderBattle(); } catch (_) {}
}

