// ---- Pet evolution (stages at +3/+6 upgrades) and dungeon bond ----
const RPG_PET_EVO = {
  loyal_pup: [["Brave Hound", "🐕"], ["Celestial Wolf", "🐺"]],
  shadow_cat: [["Midnight Panther", "🐈‍⬛"], ["Spectral Wraith", "🐯"]],
  tortoise_knight: [["Titan Shell", "🐢"], ["Diamond Guardian", "🛡️"]],
  frost_penguin: [["Glacial Sentinel", "🐧"], ["Eternal Frost", "🧊"]],
  wisp_familiar: [["Spirit Beacon", null], ["Celestial Oracle", null]],
  ember_fox: [["Infernal Vixen", "🦊"], ["Pyric Shade", "🔥"]],
  storm_chick: [["Thunder Raptor", "🐔"], ["Sky Sovereign", "🦅"]],
  owl_familiar: [["Regal Strix", null], ["Nocturnal Oracle", null]],
  star_unicorn: [["Celestial Monarch", "🦄"], ["Eternal Starlight", "🌟"]],
  pocket_dragon: [["Wyrm Lord", null], ["Draconic Sovereign", null]],
  eternal_phoenix: [["Solar Phoenix", "🐦‍🔥"], ["Cosmic Firebird", "🐦‍🔥"]]
};
function rpgPetStage(it) {
  if (!it || it.slot !== "pet") return 0;
  const up = rpgUpgradeLevel(it.id);
  return up >= 6 ? 2 : up >= 3 ? 1 : 0;
}
function rpgPetDisplayName(it) {
  const st = rpgPetStage(it);
  const evo = RPG_PET_EVO[it.id];
  return st && evo ? evo[st - 1][0] : it.name;
}
function rpgPetEvoEmoji(it) {
  const st = rpgPetStage(it);
  const evo = RPG_PET_EVO[it.id];
  return st && evo ? evo[st - 1][1] : null;
}
function rpgPetSkillMult(it) { return [1, 1.2, 1.45][rpgPetStage(it)] || 1; }
function rpgPetBondPct(petId) {
  const f = (rpgState && rpgState.petBond && rpgState.petBond[petId]) || 0;
  return Math.min(10, Math.floor(f / 10));
}
// ---- Item affixes: drops & pack pulls roll bonus names/stats (shop items are clean) ----
const RPG_PREFIXES = {
  flaming: { name: "Flaming", atk: 2 }, icy: { name: "Icy", def: 2 }, shadowed: { name: "Shadowed", crit: 3 },
  radiant: { name: "Radiant", hp: 4 }, cursed: { name: "Cursed", atk: 3, def: -1 }, swift: { name: "Swift", crit: 2, atk: 1 },
  stalwart: { name: "Stalwart", def: 2, hp: 2 }, mystic: { name: "Mystic", crit: 1, hp: 2 }, verdant: { name: "Verdant", hp: 5, atk: -1 },
  void: { name: "Void-touched", atk: 3, hp: -2 }, gilded: { name: "Gilded", hp: 1, crit: 1 }, ancient: { name: "Ancient", atk: 1, def: 1, hp: 1 }
};
const RPG_SUFFIXES = {
  power: { name: "of Power", atk: 2 }, walls: { name: "of Walls", def: 2 }, fox: { name: "of the Fox", crit: 3 },
  bear: { name: "of the Bear", hp: 5 }, viper: { name: "of the Viper", atk: 2, crit: 1 }, owl: { name: "of the Owl", crit: 2, hp: 2 },
  oak: { name: "of the Oak", def: 1, hp: 3 }, storm: { name: "of Storms", atk: 1, crit: 2 }, dawn: { name: "of Dawn", hp: 3, def: 1 },
  night: { name: "of Night", crit: 4, def: -1 }, kings: { name: "of Kings", atk: 1, def: 1, crit: 1 }, titans: { name: "of Titans", atk: 3, def: 1 }
};
function rpgAffixScale(it) { return 0.75 + RPG_RARITY[it.rarity].rank * 0.25; }
function rpgRollAffixes(it, fromPack) {
  if (!rpgState) return;
  const roll = Math.random();
  const dual = roll < (fromPack ? 0.55 : 0.25);
  const single = !dual && roll < 0.9;
  const pick = obj => { const k = Object.keys(obj); return k[Math.floor(Math.random() * k.length)]; };
  const pre = dual || (single && Math.random() < 0.5) ? pick(RPG_PREFIXES) : null;
  const suf = dual || (single && !pre) ? pick(RPG_SUFFIXES) : null;
  if (pre || suf) rpgState.affixes[it.id] = [pre, suf];
}
function rpgItemAffixes(it) {
  const a = rpgState && rpgState.affixes && rpgState.affixes[it.id];
  return a ? { pre: a[0] ? RPG_PREFIXES[a[0]] : null, suf: a[1] ? RPG_SUFFIXES[a[1]] : null } : { pre: null, suf: null };
}
function rpgDisplayName(it) {
  const { pre, suf } = rpgItemAffixes(it);
  return `${pre ? pre.name + " " : ""}${rpgPetDisplayName ? rpgPetDisplayName(it) : it.name}${suf ? " " + suf.name : ""}`;
}
function rpgRerollCost(it) { return 40 + (it.levelReq || 1) * 25; }
function rpgRerollAffixes(id) {
  const it = RPG_ITEMS_BY_ID[id];
  if (!it || !rpgState || !rpgState.inventory[id]) return;
  const cost = rpgRerollCost(it);
  if (rpgState.gold < cost) { toast(`Need 🪙 ${cost} to reroll`, "error"); return; }
  rpgState.gold -= cost;
  delete rpgState.affixes[id];
  rpgRollAffixes(it, true);
  rpgSave();
  rpgRenderCharacterPage();
  const { pre, suf } = rpgItemAffixes(it);
  toast(pre || suf ? `🔮 ${rpgDisplayName(it)}!` : "🔮 The magic fizzled — plain item", pre || suf ? "success" : "");
}
const RPG_UPGRADE_MAX = 9, RPG_UPGRADE_STEP = 0.08;
function rpgUpgradeLevel(id) {
  const lvl = (rpgState && rpgState.upgrades && rpgState.upgrades[id]) || 0;
  return Math.max(0, Math.min(RPG_UPGRADE_MAX, lvl));
}
function rpgUpgradeCost(it) {
  return Math.max(20, Math.round((it.price || 80) * 0.2 * (rpgUpgradeLevel(it.id) + 1)));
}
function rpgItemStats(it) { // effective stats including +N upgrade and class synergy
  const m = 1 + RPG_UPGRADE_STEP * rpgUpgradeLevel(it.id);
  const v = k => it[k] ? Math.round(it[k] * m) : 0;
  const s = { atk: v("atk"), def: v("def"), crit: v("crit"), hp: v("hp") };
  const { pre, suf } = rpgItemAffixes(it);
  const ax = rpgAffixScale(it);
  [pre, suf].forEach(a => {
    if (!a) return;
    s.atk += Math.round((a.atk || 0) * ax);
    s.def += Math.round((a.def || 0) * ax);
    s.crit += Math.round((a.crit || 0) * ax);
    s.hp += Math.round((a.hp || 0) * ax);
  });
  if (it.classBonus && rpgState && rpgState.clazz === it.classBonus.clazz) {
    s.atk += it.classBonus.atk || 0;
    s.def += it.classBonus.def || 0;
    s.crit += it.classBonus.crit || 0;
    s.hp += it.classBonus.hp || 0;
  }
  return s;
}
function rpgUpgradeItem(id) {
  const it = RPG_ITEMS_BY_ID[id];
  if (!it || !rpgState || !rpgState.inventory[id]) return;
  const lvl = rpgUpgradeLevel(id);
  if (lvl >= RPG_UPGRADE_MAX) { toast("Already at max upgrade (+9)!", "error"); return; }
  const cost = rpgUpgradeCost(it);
  if (rpgState.gold < cost) { toast(`Need 🪙 ${cost} to upgrade — solve more questions!`, "error"); return; }
  rpgState.gold -= cost;
  rpgState.upgrades[id] = lvl + 1;
  rpgSave();
  rpgPublishLeaderboard();
  rpgRenderCharacterPage();
  rpgRenderBattle();
  toast(`${it.name} upgraded to +${lvl + 1} ⚒️`, "success");
}

