function advSkillDesc(d) {
  const bits = [];
  if (d.kind === "hit") bits.push(`strikes for ${Math.round(d.mult * 100)}% damage`);
  if (d.kind === "multi") bits.push(`${d.hits} quick strikes of ${Math.round(d.mult * 100)}%`);
  if (d.kind === "volley") bits.push(`fires ${d.hits} arrows of ${Math.round(d.mult * 100)}% at random enemies (some may miss)`);
  if (d.kind === "aoe") bits.push(`hits ALL enemies for ${Math.round(d.mult * 100)}%`);
  if (d.kind === "chain") bits.push(`chain lightning across ${d.jumps + 1} enemies`);
  if (d.kind === "pierce") bits.push(`pierces armour for ${Math.round(d.mult * 100)}%`);
  if (d.kind === "heal") bits.push(`heals ${Math.round(d.pct * 100)}% HP`);
  if (d.kind === "slow") bits.push("chills all enemies, slowing their attacks");
  if (d.kind === "block") bits.push("blocks the next enemy hit");
  if (d.pierce && d.kind !== "pierce") bits.push("ignores armour");
  if (d.exec) bits.push("double damage on weakened enemies");
  if (d.poison) bits.push("poisons");
  if (d.burn) bits.push("burns");
  if (d.chill) bits.push("chills");
  if (d.stun) bits.push("stuns");
  if (d.lifesteal) bits.push(`heals ${Math.round(d.lifesteal * 100)}% of damage dealt`);
  if (d.healPct) bits.push(`restores ${Math.round(d.healPct * 100)}% HP`);
  return `${d.name} (${d.cd}s): ` + bits.join(", ");
}
function advWaveTiers(floorOffset = 0) {
  // difficulty follows the FLOOR, not the hero's level — levelling up must
  // always make earlier floors easier. Raw tiers may exceed 10 on deep
  // floors — enemies are picked at tier 10 and scaled up instead, so the
  // dungeon never stops getting harder.
  const f = floorOffset + 1;
  return [f - 1, f, f, f + 1, f + 2].map(t => Math.max(1, t));
}
// hordes: waves are packed with weak fodder so AOE, chain and volleys mow them down
function advWaveComp(w) {
  const t = adv.tiers[w], mt = Math.max(1, t - 1);
  const fodder = n => Array.from({ length: n }, () => ({ tier: mt, minion: true }));
  if (w === ADV_WAVES - 1) return [{ tier: t, boss: true }].concat(fodder(4));
  if (w === 0) return fodder(3);
  if (w === 1) return [{ tier: t }].concat(fodder(3));
  if (w === 2) return [{ tier: t }].concat(fodder(4));
  return [{ tier: t }].concat(fodder(5));
}
function advBarHtml(id) { return `<div class="rpg-bar adv-bar"><div class="rpg-bar-fill hp" id="${id}" style="width:100%;"></div></div>`; }
function advSetBar(id, frac) { const el = $(id); if (el) el.style.width = Math.max(0, Math.round(frac * 100)) + "%"; }
function advOverlay(html) {
  const o = $("advOverlay");
  if (!o) return;
  if (html) { o.innerHTML = html; o.classList.add("show"); }
  else { o.classList.remove("show"); o.innerHTML = ""; }
}
function advUpdateRunsChip() {
  const chip = $("advRunsChip");
  if (chip) chip.textContent = rpgCanPreview() ? "∞ runs (teacher preview)" : `🎮 ${advRunsLeft()} game credit${advRunsLeft() === 1 ? "" : "s"} left today`;
}
function advHeroHtml() {
  return `<div class="adv-tag">${escapeHtml((currentUser && currentUser.name) || "You")}</div>` + rpgAvatarSvg() + advBarHtml("advHeroHp");
}
function advEquippedSkills() {
  const out = [];
  const w = rpgState.equipment.weapon, p = rpgState.equipment.pet;
  if (w && RPG_SKILLS[w]) out.push({ owner: "weapon", id: w, def: RPG_SKILLS[w], readyAt: 0 });
  if (p && RPG_SKILLS[p]) {
    const base = RPG_SKILLS[p];
    const m = rpgPetSkillMult(RPG_ITEMS_BY_ID[p]);
    const def = m > 1 ? Object.assign({}, base, { mult: base.mult != null ? Math.round(base.mult * m * 100) / 100 : undefined, pct: base.pct != null ? Math.round(base.pct * m * 100) / 100 : undefined }) : base;
    out.push({ owner: "pet", id: p, def, readyAt: 0 });
  }
  rpgClassActives().forEach(n => out.push({ owner: "class", id: n.id, def: rpgTreeActiveDef(n), readyAt: 0 }));
  return out;
}
function advSkillbarHtml(skills) {
  if (!skills.length) return `<div class="adv-status">Equip a weapon (and a pet!) to unlock skills</div>`;
  return skills.map((s, i) =>
    `<div class="adv-skill ready" id="advSkill${i}" title="${escapeHtml(advSkillDesc(s.def))}">
      <div class="adv-skill-tile"><span>${s.def.icon}</span><div class="adv-skill-cd" id="advSkillCd${i}"></div><span class="adv-skill-time" id="advSkillT${i}"></span></div>
      <span class="adv-skill-owner">${s.owner === "pet" ? "🐾" : s.owner === "class" ? (RPG_CLASSES[rpgState.clazz] ? RPG_CLASSES[rpgState.clazz].icon : "📜") : "⚔️"}</span>
      <span class="adv-skill-name">${escapeHtml(s.def.name)}</span>
    </div>`).join("");
}
function rpgRenderAdventure() {
  if (!rpgState || adv) return;
  advUpdateRunsChip();
  $("advHero").innerHTML = advHeroHtml();
  $("advFoes").innerHTML = "";
  const wEl = $("advFoes");
  if (wEl && wEl.style) wEl.style.transform = "";
  $("advSkillbar").innerHTML = advSkillbarHtml(advEquippedSkills());
  $("advStatus").textContent = "";
  $("advWaveChip").style.display = "none";
  $("advQuitBtn").style.display = "none";
  $("advStartBtn").style.display = "";
  $("advStage").classList.remove("walking");
  const best = (rpgState.stats && rpgState.stats.bestFloor) || 0;
  const floor = advDungeonFloor();
  advOverlay(advRunsLeft() > 0 || rpgCanPreview()
    ? `<div><h4>🏰 The Dungeon awaits — Floor ${floor}</h4><p>Your hero fights on their own — skills and pet abilities cast automatically. Each raid you descend up to <b>${ADV_FLOORS_PER_RAID} floors</b>, then make camp; your progress is saved and the next raid continues from where you stopped. Each raid spends <b>1 game credit</b> (${advRunsLeft()} left today).${best > 1 ? ` Your deepest: <b>Floor ${best}</b>.` : ""}</p></div>`
    : `<div><h4>🎮 Out of game credits</h4><p>You've used all your game credits for today. Answer <b>5 questions</b> in any practice mode to earn another, or come back tomorrow to descend from <b>Floor ${floor}</b>.</p></div>`);
}
function advStart() {
  if (!rpgState || adv) return;
  if (!rpgCanPreview() && _creditsLeft() <= 0) { toast("Out of game credits — answer 5 questions to earn one, or come back tomorrow!", "error"); return; }
  if (!rpgCanPreview()) _spendCredit();
  advToken++;
  const stats = rpgPlayerStats();
  const startFloor = advDungeonFloor(); // resume the climb from where the last raid stopped
  adv = { phase: "walk", wave: 0, floor: startFloor, startFloor, tiers: advWaveTiers(startFloor - 1), stats, heroHp: stats.maxHp, heroMax: stats.maxHp,
    foes: [], skills: advEquippedSkills(), shield: 0, heroNextAtk: 0, heroX: 0, heroInRange: false, worldX: 0, scroll: 0, lurch: 0, gold: 0, xp: 0, kills: 0, loopId: 0, rafOn: false, mods: { atkPct: 0, goldPct: 0, cdr: 0, dr: 0, leech: 0, el: {} } };
  adv.loopId = setInterval(advTick, ADV_TICK_MS);
  adv.rafOn = true;
  advRafLast = 0;
  if (typeof requestAnimationFrame === "function") requestAnimationFrame(advRaf);
  advOverlay("");
  advUpdateRunsChip();
  $("advStartBtn").style.display = "none";
  $("advQuitBtn").style.display = "";
  $("advHero").innerHTML = advHeroHtml();
  $("advSkillbar").innerHTML = advSkillbarHtml(adv.skills);
  advWalk();
}
