function advShowDraft() {
  adv.phase = "draft";
  adv.scrollTarget = 0;
  const pool = RPG_DRAFTS.filter(d => !d.tier || (d.tier === 2 && adv.floor >= 4) || (d.tier === 3 && adv.floor >= 8));
  const picks = pool.slice().sort(() => Math.random() - 0.5).slice(0, 3);
  adv.draftOffer = picks;
  advOverlay(`<div><h4>🏕️ Floor ${adv.floor} cleared — choose a blessing</h4>
    <div class="adv-draft-row">${picks.map((d, i) =>
      `<button class="adv-draft-card" type="button" data-rpg-draft="${i}"><span class="adv-draft-ico">${d.icon}</span><b>${escapeHtml(d.name)}</b><span>${escapeHtml(d.desc)}</span></button>`).join("")}</div></div>`);
}
function advPickDraft(i) {
  if (!adv || adv.phase !== "draft" || !adv.draftOffer) return;
  const d = adv.draftOffer[i];
  if (!d) return;
  const m = adv.mods;
  if (d.el) m.el[d.el] = (m.el[d.el] || 0) + 0.3;
  if (d.atkPct) m.atkPct += d.atkPct;
  if (d.goldPct) m.goldPct += d.goldPct;
  if (d.cdr) m.cdr = Math.min(0.5, m.cdr + d.cdr);
  if (d.dr) m.dr += d.dr;
  if (d.leech) m.leech += d.leech;
  if (d.vuln) m.vuln = (m.vuln || 0) + d.vuln;
  if (d.chillBonus) m.chillBonus = (m.chillBonus || 0) + d.chillBonus;
  if (d.exePower) m.exePower = Math.max(m.exePower || 0, d.exePower);
  if (d.reflect) m.reflect = (m.reflect || 0) + d.reflect;
  if (d.scalingFloor) m.scalingFloor = true;
  if (d.healNow) advHeal(adv.heroMax * d.healNow, d.icon);
  adv.draftOffer = null;
  advOverlay("");
  toast(`${d.icon} ${d.name}!`, "success");
  adv.floor++;
  adv.wave = 0;
  adv.tiers = advWaveTiers(adv.floor - 1);
  adv.phase = "between";
  advAfter(700, advWalk);
}
// ---- Ghost Arena: duel an AI copy of a classmate's published build ----
function rpgGhostStats(row) {
  const lvl = Math.max(1, row.level || 1);
  const eq = row.equipment || {};
  let atk = 4 + lvl, def = 0, crit = 5, hp = 40 + lvl * 10;
  Object.values(eq).filter(Boolean).forEach(id => {
    const it = RPG_ITEMS_BY_ID[id];
    if (!it) return;
    atk += it.atk || 0; def += it.def || 0; crit += it.crit || 0; hp += it.hp || 0;
  });
  if (row.clazz === "warrior") { hp = Math.round(hp * 1.1); def = Math.round(def * 1.15) + 1; }
  if (row.clazz === "rogue") crit += 8;
  return { atk, def, crit: Math.min(75, crit), maxHp: hp, weapon: eq.weapon || null };
}
