// Push the current plays-left pool into any running game iframe so an open
// game unlocks immediately after a refill.
function _pushPlaysLeft() {
  const payload = { type: 'SD_PLAYS_LEFT', playsLeft: _playsLeftPayload() };
  ['defendersFrame', 'raidersFrame', 'spireFrame', 'legendsFrame', 'slayersFrame'].forEach(id => {
    const f = document.getElementById(id);
    try { f && f.contentWindow && f.contentWindow.postMessage(payload, '*'); } catch (e) {}
  });
}
async function adminResetGameCredits() {
  if (!currentUser || currentUser.role !== 'admin') return;
  if (!confirm("Refill game credits for ALL students right now?\n\nEvery student's pool is topped back up to their full daily allowance today. Students with more credits than the allowance keep what they have.")) return;
  try {
    await setDoc(doc(db, 'users', currentUser.uid, 'settings', 'creditReset'), {
      key: Date.now().toString(36),
      day: _todayKey(),
      at: new Date().toISOString(),
      by: currentUser.name || 'Admin'
    });
    showToast('🎮 Game credits refilled for all students', 'success');
  } catch (e) {
    console.warn('credit reset failed', e);
    showToast('Could not send the reset — check your connection', 'error');
  }
}
// Credits remaining today. Admins / teacher-preview are never limited.
function _creditsLeft() {
  if (!currentUser || currentUser.role !== 'student') return 99;
  return Math.max(0, _creditsToday().balance | 0);
}
// Questions still needed before the next credit is earned.
function _creditsToNextReward() {
  if (!currentUser || currentUser.role !== 'student' || !rpgState) return 0;
  return Math.max(1, Math.ceil(CREDITS_PER_REWARD - (_creditsToday().qProgress || 0)));
}
// Spend one credit to start a game. Returns true if a credit was available.
function _spendCredit() {
  if (!currentUser || currentUser.role !== 'student' || !rpgState) return true; // no limit for admins/preview
  const c = _creditsToday();
  if ((c.balance | 0) <= 0) return false;
  c.balance = (c.balance | 0) - 1;
  try { rpgSave(); } catch (e) {}
  try { rpgRenderSide(); } catch (e) {}
  return true;
}
// Count a finished question (a non-game mode) toward the next earned credit.
// A fresh question is a full step; a question already done today still gives a
// HALF step once (revision / small banks shouldn't stall the meter entirely),
// then stops counting for the rest of the day.
function _noteQuestionForCredit(qid) {
  if (!currentUser || currentUser.role !== 'student' || !rpgState) return;
  const c = _creditsToday();
  const key = String(qid || '');
  let step = 1;
  if (key) {
    const n = c.qSeen[key] || 0;
    if (n >= 2) return;            // already gave its full + repeat credit today
    if (n === 1) step = 0.5;       // repeat today → half progress, once
    c.qSeen[key] = n + 1;
  }
  c.qProgress = (c.qProgress || 0) + step;
  let earned = 0;
  while (c.qProgress >= CREDITS_PER_REWARD) { c.qProgress -= CREDITS_PER_REWARD; c.balance = (c.balance | 0) + 1; earned++; }
  if (earned > 0) { try { toast(`🎮 +${earned} game credit${earned > 1 ? 's' : ''} earned — ${_creditsLeft()} left today`, 'success'); } catch (e) {} }
  try { rpgSave(); } catch (e) {}
  try { rpgRenderSide(); } catch (e) {}
}
// The mini-games gate on playsLeft[mode]; every mode reads the same shared pool.
function _playsLeftPayload() { const n = _creditsLeft(); return { defenders: n, raiders: n, spire: n, legends: n, slayers: n }; }

// ---- ⚡ Energy bar: 50 correct answers → one free 💠 Gold Pack ----
// A faucet, so it obeys the same rule points do: it fills ONLY on a correct
// answer that already paid out — a marked practice question, or a game
// question that passed the rushed-answer and wrong-run guards. No button can
// advance it. The pack is banked UNOPENED (`energy.pending`) rather than torn
// open on the spot: the reveal ceremony belongs on the Realm of Embers page,
// not on top of the question the student is in the middle of answering.
const ENERGY_PER_PACK = 50;        // correct answers to fill the bar once
const ENERGY_PACK_ID = 'galaxy';   // 💠 Gold Pack — see TCG_PACKS
function _energyState() {
  if (!rpgState) return null;
  let e = rpgState.energy;
  if (!e || typeof e !== 'object') e = rpgState.energy = {};
  const pos = v => { v = Number(v); return (isFinite(v) && v > 0) ? v : 0; };
  // rpgNoteEnergy always drains a full bar into `pending`, so a stored fill is
  // below one pack by construction — clamping to that keeps a corrupted or
  // hand-edited value from sitting on a permanently "full" bar.
  e.fill = Math.min(Math.round(pos(e.fill)), ENERGY_PER_PACK - 1);
  e.pending = Math.min(Math.round(pos(e.pending)), 99);
  e.packs = Math.round(pos(e.packs));
  return e;
}
function rpgEnergyPct() {
  const e = _energyState();
  return e ? Math.max(0, Math.min(100, Math.round((e.fill / ENERGY_PER_PACK) * 100))) : 0;
}
// Count correct answers toward the bar. `n` is only ever > 1 when a batch is
// claimed back from Science Strike, which banks its correct answers instead of
// writing the hero doc itself. Returns how many packs that filled.
function rpgNoteEnergy(n = 1) {
  if (!rpgState || !currentUser || currentUser.role !== 'student') return 0;
  const e = _energyState();
  if (!e) return 0;
  n = Math.round(Number(n) || 0);
  if (n <= 0) return 0;
  n = Math.min(n, ENERGY_PER_PACK * 4);   // sanity ceiling on any single claim
  e.fill += n;
  let earned = 0;
  while (e.fill >= ENERGY_PER_PACK) { e.fill -= ENERGY_PER_PACK; e.pending = (e.pending | 0) + 1; e.packs = (e.packs | 0) + 1; earned++; }
  if (earned > 0) {
    try {
      toast('⚡ Energy full! ' + (earned === 1 ? 'A free 💠 Gold Pack is' : earned + ' free 💠 Gold Packs are')
        + ' waiting for you in 🔥 Realm of Embers', 'success');
    } catch (_) {}
  }
  try { rpgSave(); } catch (_) {}
  try { rpgRenderSide(); } catch (_) {}
  if (earned > 0) try { _tcgRefreshIfOpen(); } catch (_) {}
  return earned;
}
// Repaint the Realm of Embers body only when that page is actually on screen —
// the energy bar can fill from anywhere in the app.
function _tcgRefreshIfOpen() {
  const pg = document.getElementById('page-tcg');
  if (pg && pg.classList.contains('active') && typeof tcgRenderBody === 'function') tcgRenderBody();
}
// Open one banked free Gold Pack. Costs nothing — it was already paid for with
// 50 correct answers.
function tcgOpenFreePack() {
  const e = _energyState();
  if (!e || (e.pending | 0) <= 0) return;
  const p = TCG_PACKS.find(x => x.id === ENERGY_PACK_ID);
  if (!p || !tcgState()) return;
  e.pending = (e.pending | 0) - 1;   // spend first, so a mid-open error cannot re-grant it
  _tcgOpenPack(p, tcgPackSet);       // the set chosen on the Packs tab, same as a bought pack
  try { rpgRenderSide(); } catch (_) {}
}

// ---- No-repeat rotation for game questions (invisible to students) ----
// A per-student localStorage map stamps every question a game mode serves with
// the time it was last shown. Games receive never-served questions first; when
// those run low, the payload is topped up with the least-recently-served ones
// so a run always has enough variety and nothing comes back until everything
// else has had a turn. The key is shared with Science Strike (fps.html) so the
// rotation spans every game mode, and the map is never bulk-reset — recency
// alone decides what rotates back in. Internal bookkeeping only — the stamps
// are never rendered anywhere a student can see.
function _gqKey() { return 'gameQSeen_' + ((currentUser && currentUser.uid) || 'guest'); }
function _gqLoad() { try { return JSON.parse(localStorage.getItem(_gqKey())) || {}; } catch (e) { return {}; } }
function _gqSave(m) { try { localStorage.setItem(_gqKey(), JSON.stringify(m)); } catch (e) {} }
// The games' built-in demo/fallback questions (b0…b7, sp_f*, builtin_*) must
// never enter the rotation map — those ids don't exist in the real bank.
function _gqRealId(id) { return !!id && !/^(b\d+|sp_f\d+|builtin_\d+)$/.test(String(id)); }
function _gqMark(id) { if (!_gqRealId(id)) return; const m = _gqLoad(); m[id] = Date.now(); _gqSave(m); }
function _gqFilterPool(pool) {
  if (!Array.isArray(pool) || pool.length < 2) return pool;
  const m = _gqLoad();
  const unseen = [], seenQs = [];
  for (const q of pool) { if (q) (m[q.id] ? seenQs : unseen).push(q); }
  // A run needs a decent spread of questions, so the payload never shrinks
  // below a floor (or the whole pool when it's smaller than the floor).
  const floor = Math.min(pool.length, Math.max(12, Math.min(30, Math.ceil(pool.length / 3))));
  if (unseen.length >= floor) return unseen;
  // Top up with the least-recently-served. Legacy cycle counters (tiny
  // numbers) sort as ancient stamps, so they rotate back in first — no
  // migration needed.
  seenQs.sort((a, b) => (m[a.id] || 0) - (m[b.id] || 0));
  return unseen.concat(seenQs.slice(0, floor - unseen.length));
}

// Build the SD_QUESTIONS payload for a game frame: bank (or past-paper pool)
// → hidden no-repeat rotation → cross-mode attempt stats. Reused by the
// initial frame request AND every run start, so long sittings never play from
// a stale pool snapshot.
async function _sdQuestionsPayload(source) {
  let questions = [];
  // Past-paper mode: the game launched from the Past Papers page gets ONLY
  // the selected portion's attached questions (MCQ + OEQ self-check).
  const ppMode = _ppGameFrameMatches(source);
  try { questions = ppMode ? ppGamePool(_ppGameSel.year) : buildDefenderQuestions(); } catch (e) { console.warn('SD bank extract failed', e); }
  // rotation: never-served questions first, least-recently-served top-up
  try { questions = _gqFilterPool(questions); } catch (e) { console.warn('gq filter', e); }
  const seenStats = await _sdSeenStats();
  return {
    type: 'SD_QUESTIONS',
    questions,
    seenIds: Object.keys(seenStats),
    seenStats,
    studentKey: (currentUser && currentUser.uid) || 'guest',
    studentName: (currentUser && currentUser.name) || '',
    playLimit: _dailyCreditAllowance(),
    playsLeft: _playsLeftPayload()
  };
}
window.addEventListener('message', function (ev) {
  const d = ev && ev.data;
  if (!d) return;
  if (d.type === 'SD_REQUEST_QUESTIONS') {
    (async () => {
      const payload = await _sdQuestionsPayload(ev.source);
      try { ev.source && ev.source.postMessage(payload, '*'); } catch (e) {}
    })();
  } else if (d.type === 'SD_RECORD') {
    try { _gqMark(d && d.questionId); } catch (e) {}   // stamp it as served in the rotation
    _sdRecordAttempt(d);
    // Defenders / Raiders / Legends / Slayers / Spire all report answers
    // through this one message, so paying here pays every one of them.
    try {
      const pts = rpgAwardGameQuestion(d.questionId, !!d.correct, d.ms);
      if (pts) ev.source && ev.source.postMessage({ type: 'SD_POINTS', points: pts, runTotal: _gameRunPts }, '*');
    } catch (e) {}
  } else if (d.type === 'SD_SHOWN') {
    // A game displayed this question (answered or not — skips and abandoned
    // runs count too), so the rotation must not serve it again soon.
    try { _gqMark(d && d.questionId); } catch (e) {}
  } else if (d.type === 'SD_FLAG') {
    _sdRecordFlag(d, ev.source);
  } else if (d.type === 'SD_SCORE') {
    _sdRecordScore(d);
  } else if (d.type === 'RAIDERS_REQUEST_ASSETS') {
    (async () => {
      const overrides = await loadRaidersOverrides();
      try { ev.source && ev.source.postMessage({ type: 'raidersAssets', overrides }, '*'); } catch (e) {}
    })();
  } else if (d.type === 'SPIRE_REQUEST_ASSETS') {
    (async () => {
      const payload = await spireAssetsPayload();
      try { ev.source && ev.source.postMessage(payload, '*'); } catch (e) {}
    })();
  } else if (d.type === 'SD_PLAY_START') {
    _spendCredit();
    _gamePtsReset();   // the header readout counts THIS run
    try { ev.source && ev.source.postMessage({ type: 'SD_PLAYS_LEFT', playsLeft: _playsLeftPayload() }, '*'); } catch (e) {}
    // Every run start also gets a freshly rotation-filtered pool, so questions
    // served earlier in the sitting (in this or any other game) drop out.
    (async () => {
      const payload = await _sdQuestionsPayload(ev.source);
      try { ev.source && ev.source.postMessage(payload, '*'); } catch (e) {}
    })();
  } else if (d.type === 'LEGENDS_REQUEST_ASSETS') {
    (async () => {
      const overrides = await loadLegendsSpriteOverrides();
      try { ev.source && ev.source.postMessage({ type: 'legendsAssets', overrides }, '*'); } catch (e) {}
    })();
  } else if (d.type === 'LEGENDS_SPRITES') {
    _legendsThumbs = d.thumbs || {};
  } else if (d.type === 'LEGENDS_REQUEST_META') {
    try { ev.source && ev.source.postMessage({ type: 'LEGENDS_META', meta: (rpgState && rpgState.legends) || {}, gold: rpgState ? (rpgState.gold | 0) : 0 }, '*'); } catch (e) {}
  } else if (d.type === 'LEGENDS_GOLD_DELTA') {
    _legendsGoldDelta(d, ev.source);
  } else if (d.type === 'LEGENDS_SAVE') {
    _legendsSaveMeta(d, ev.source);
  }
});

// =====================================================================
// SCIENCE LEGENDS (beta) — permanent gear & loot boxes.
// The game's Armory lives in the iframe; the wallet is the hero's gold
// (the points students earn in the app), and the inventory/equipment/
// loadout persist on rpgState.legends so gear follows the student
// across devices, like the Spire card collection.
// =====================================================================
// Only the game iframes this page embeds may move the wallet. Without this any
// window that can postMessage here — including the console on this very page —
// could repeat a positive LEGENDS_GOLD_DELTA for unlimited points.
function _isEmbeddedGameWindow(source) {
  if (!source) return false;
  return ['legendsFrame', 'slayersFrame'].some(id => {
    const f = document.getElementById(id);
    try { return !!f && f.contentWindow === source; } catch (e) { return false; }
  });
}
function _legendsGoldDelta(d, source) {
  const reason = (d && d.reason) || '';
  function reply(ok, message) {
    try { source && source.postMessage({ type: 'LEGENDS_GOLD_RESULT', ok, reason, message: message || '', gold: rpgState ? (rpgState.gold | 0) : 0 }, '*'); } catch (e) {}
  }
  if (!rpgState) { reply(false, 'No hero yet — answer a question in the app first'); return; }
  const delta = Math.round(Number(d && d.delta) || 0);
  // A spend can come from anywhere (it only ever costs the student); a CREDIT
  // must come from the embedded Armory itself.
  if (delta > 0 && !_isEmbeddedGameWindow(source)) { reply(false, 'Points can only be credited from inside the game'); return; }
  if (!delta || delta < -2000 || delta > 500) { reply(false, 'Invalid amount'); return; }
  if (delta < 0 && (rpgState.gold | 0) + delta < 0) { reply(false, `Not enough points — that costs 🪙 ${-delta}. Answer questions to earn more!`); return; }
  rpgState.gold = (rpgState.gold | 0) + delta;
  rpgSave();
  reply(true);
}
function _legendsSaveMeta(d, source) {
  if (!rpgState || !d || !d.meta || typeof d.meta !== 'object') return;
  const m = d.meta;
  const cur = (rpgState.legends && typeof rpgState.legends === 'object') ? rpgState.legends : {};
  const curInv = Array.isArray(cur.inv) ? cur.inv.length : 0;
  const newInv = Array.isArray(m.inv) ? m.inv.length : 0;
  const curTs = cur.ts || 0, newTs = m.ts || 0;
  // Refuse stale writes and suspicious wipes: a game frame that hasn't synced
  // down yet (or a second open game with an old copy) must never erase the
  // armory. Resync the sender with the good copy instead of saving.
  if ((curTs && newTs && newTs < curTs) || (curInv >= 2 && newInv === 0)) {
    try { source && source.postMessage({ type: 'LEGENDS_META', meta: cur, gold: rpgState.gold | 0 }, '*'); } catch (e) {}
    return;
  }
  rpgState.legends = {
    inv: Array.isArray(m.inv) ? m.inv.slice(0, 100) : [],
    eq: (m.eq && typeof m.eq === 'object') ? m.eq : {},
    loadout: (m.loadout && typeof m.loadout === 'object') ? m.loadout : {},
    follower: typeof m.follower === 'string' ? m.follower : 'fdef',
    ts: newTs || Date.now()
  };
  rpgSave();
  // keep BOTH game frames on the fresh copy so a stale frame can't clobber it
  ['legendsFrame', 'slayersFrame'].forEach(id => {
    const f = document.getElementById(id);
    try { f && f.contentWindow && f.contentWindow !== source && f.contentWindow.postMessage({ type: 'LEGENDS_META', meta: rpgState.legends, gold: rpgState.gold | 0 }, '*'); } catch (e) {}
  });
}

// Record a finished mini-game run's score so it can rank on the leaderboard.
// Best score is kept all-time AND per-month (the month bests drive the monthly
// $10 vouchers). Stored on the hero state and republished to the shared board.
function _sdRecordScore(d) {
  try {
    if (!rpgState || !currentUser || currentUser.role !== 'student') return;
    const key = _gameModeKey(d && d.mode);
    const score = Math.max(0, Math.round(Number(d && d.score) || 0));
    if (!score) return;
    rpgEnsureGameScores();
    const g = rpgState.gameScores[key];
    if (score > (g.best || 0)) { g.best = score; g.bestLabel = (d.label || '') + ''; }
    if (score > (g.monthBest || 0)) { g.monthBest = score; g.monthLabel = (d.label || '') + ''; }
    rpgSave();
    rpgPublishLeaderboard();
  } catch (e) { console.warn('SD score record failed', e); }
}

