// Default-art thumbnails, generated by the game in a tiny hidden iframe.
let _legendsThumbs = null, _legendsThumbWait = null;
function loadLegendsThumbs(){
  if (_legendsThumbs) return Promise.resolve(_legendsThumbs);
  if (_legendsThumbWait) return _legendsThumbWait;
  _legendsThumbWait = new Promise(res => {
    let f = document.getElementById('legendsThumbFrame');
    if (!f){
      f = document.createElement('iframe');
      f.id = 'legendsThumbFrame';
      f.style.cssText = 'position:absolute;width:2px;height:2px;opacity:0;pointer-events:none;left:-9999px;top:-9999px;';
      f.src = 'science-legends.html';
      document.body.appendChild(f);
    }
    let tries = 0;
    const ask = () => {
      if (_legendsThumbs) return res(_legendsThumbs);
      try { f.contentWindow && f.contentWindow.postMessage({ type: 'LEGENDS_REQUEST_SPRITES' }, '*'); } catch (e) {}
      if (++tries < 12) setTimeout(ask, 600); else res(_legendsThumbs || {});
    };
    setTimeout(ask, 500);
  });
  return _legendsThumbWait;
}
async function _legendsArtApply(id, dataUrl){
  try {
    if (!/^data:image\//i.test(dataUrl)) throw new Error('Not an image');
    const scaled = await _scaleDownDataUrl(dataUrl, 256);
    const url = await uploadImageDataUrl(scaled);
    const uid = _raidersOwnerUid(); if (!uid) throw new Error('Not signed in');
    await setDoc(_legendsSpritesDocRef(uid), { overrides: { [id]: url } }, { merge: true });
    (_legendsSpritesCache = _legendsSpritesCache || {})[id] = url;
    await loadGameAssets();
    pushLegendsAssets();
    showToast('Legends sprite updated', 'success');
  } catch (e) { console.error('legends art update', e); showToast('Update failed: ' + (e && e.message ? e.message : e), 'error'); }
}
function onLegendsObjPaste(id, e){
  const items = (e.clipboardData && e.clipboardData.items) || [];
  for (const it of items){ if (it.type && it.type.startsWith('image/')){ e.preventDefault(); _raidersFileToDataUrl(it.getAsFile(), du => _legendsArtApply(id, du)); return; } }
  showToast('No image in clipboard — copy a PNG first', 'error');
}
function onLegendsObjDrop(id, e){ e.preventDefault(); if (e.currentTarget) e.currentTarget.classList.remove('drag'); const file = e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0]; _raidersFileToDataUrl(file, du => _legendsArtApply(id, du)); }
function onLegendsObjPick(id, e){ const file = e.target && e.target.files && e.target.files[0]; _raidersFileToDataUrl(file, du => _legendsArtApply(id, du)); if (e.target) e.target.value = ''; }
async function resetLegendsObj(id){
  try {
    const uid = _raidersOwnerUid(); if (!uid) return;
    await setDoc(_legendsSpritesDocRef(uid), { overrides: { [id]: deleteField() } }, { merge: true });
    if (_legendsSpritesCache) delete _legendsSpritesCache[id];
    await loadGameAssets();
    pushLegendsAssets();
    showToast('Reset to default', 'success');
  } catch (e) { console.error('legends art reset', e); showToast('Reset failed', 'error'); }
}

function _loadRaidersSheet(key){
  return new Promise((res, rej) => {
    if (_raidersSheetImg[key]) return res(_raidersSheetImg[key]);
    const im = new Image();
    im.onload = () => { _raidersSheetImg[key] = im; res(im); };
    im.onerror = rej;
    im.src = RAIDERS_SHEETS[key];
  });
}
function _raidersTileThumb(sheetImg, idx, size){
  const c = document.createElement('canvas'); c.width = size; c.height = size;
  const cx = c.getContext('2d'); cx.imageSmoothingEnabled = false;
  cx.drawImage(sheetImg, (idx % 12) * 16, ((idx / 12) | 0) * 16, 16, 16, 0, 0, size, size);
  return c.toDataURL('image/png');
}

async function loadGameAssets(){
  const host = document.getElementById('gameAssetsGrid');
  if (!host) return;
  host.innerHTML = '<div class="ga-loading">Loading…</div>';
  try { await Promise.all([_loadRaidersSheet('dungeon'), _loadRaidersSheet('town')]); } catch (e) { console.warn('sheet load failed', e); }
  await loadRaidersOverrides(true);
  const cats = {};
  RAIDERS_OBJECTS.forEach(o => { (cats[o.cat] = cats[o.cat] || []).push(o); });
  let html = '<h2 class="ga-game">👾 Science Raiders</h2>';
  Object.keys(cats).forEach(cat => {
    html += '<h3 class="ga-cat">' + cat + '</h3><div class="ga-cards">';
    cats[cat].forEach(o => {
      const ov = _raidersOverridesCache[o.id];
      const sheet = _raidersSheetImg[o.sheet];
      const thumb = ov ? ov : (sheet ? _raidersTileThumb(sheet, o.idx, 64) : '');
      html += '<div class="ga-card" id="gacard-' + o.id + '">'
        + '<div class="ga-prev">' + (thumb ? '<img src="' + thumb + '" alt="' + o.label + '">' : '') + '</div>'
        + '<div class="ga-name">' + o.label + '</div>'
        + '<div class="ga-zone" id="gazone-' + o.id + '" tabindex="0"'
        +   ' onpaste="onRaidersObjPaste(\'' + o.id + '\', event)"'
        +   ' ondragover="event.preventDefault(); this.classList.add(\'drag\')"'
        +   ' ondragleave="this.classList.remove(\'drag\')"'
        +   ' ondrop="onRaidersObjDrop(\'' + o.id + '\', event)"'
        +   ' onclick="this.focus()">Click, then paste a PNG — or drop one here</div>'
        + '<div class="ga-actions">'
        +   '<label class="btn btn-outline ga-mini">Upload<input type="file" accept="image/*" style="display:none" onchange="onRaidersObjPick(\'' + o.id + '\', event)"></label>'
        +   (ov ? '<button class="btn btn-ghost ga-mini" onclick="resetRaidersObj(\'' + o.id + '\')">Reset</button>' : '')
        + '</div>'
        + '<div class="ga-status ' + (ov ? 'custom' : '') + '" id="gastatus-' + o.id + '">' + (ov ? '● Custom' : 'Default') + '</div>'
        + '</div>';
    });
    html += '</div>';
  });

  // ===== Science Legends — every object in the action RPG (beta) =====
  await loadLegendsSpriteOverrides(true);
  const legThumbs = await loadLegendsThumbs();
  const legCats = {};
  LEGENDS_OBJECTS.forEach(o => { (legCats[o.cat] = legCats[o.cat] || []).push(o); });
  html += '<h2 class="ga-game">⚔️ Science Legends <span style="font-weight:400;font-size:0.8rem;color:#94a3b8;">— paste a PNG to replace any hero, follower, summon, enemy or the ground tile (square images look best)</span></h2>';
  Object.keys(legCats).forEach(cat => {
    html += '<h3 class="ga-cat">' + cat + '</h3><div class="ga-cards">';
    legCats[cat].forEach(o => {
      const ov = _legendsSpritesCache[o.id];
      const thumb = ov || legThumbs[o.id] || '';
      html += '<div class="ga-card" id="lgcard-' + o.id + '">'
        + '<div class="ga-prev">' + (thumb ? '<img src="' + thumb + '" alt="' + o.label + '">' : '<div style="font-size:34px;line-height:64px;text-align:center;opacity:.7;">' + o.em + '</div>') + '</div>'
        + '<div class="ga-name">' + o.label + '</div>'
        + '<div class="ga-zone" id="lgzone-' + o.id + '" tabindex="0"'
        +   ' onpaste="onLegendsObjPaste(\'' + o.id + '\', event)"'
        +   ' ondragover="event.preventDefault(); this.classList.add(\'drag\')"'
        +   ' ondragleave="this.classList.remove(\'drag\')"'
        +   ' ondrop="onLegendsObjDrop(\'' + o.id + '\', event)"'
        +   ' onclick="this.focus()">Click, then paste a PNG — or drop one here</div>'
        + '<div class="ga-actions">'
        +   '<label class="btn btn-outline ga-mini">Upload<input type="file" accept="image/*" style="display:none" onchange="onLegendsObjPick(\'' + o.id + '\', event)"></label>'
        +   (ov ? '<button class="btn btn-ghost ga-mini" onclick="resetLegendsObj(\'' + o.id + '\')">Reset</button>' : '')
        + '</div>'
        + '<div class="ga-status ' + (ov ? 'custom' : '') + '" id="lgstatus-' + o.id + '">' + (ov ? '● Custom' : 'Default') + '</div>'
        + '</div>';
    });
    html += '</div>';
  });

  // ===== Avatar & Items — replace the hero ragdoll + gear SVGs with PNGs =====
  await loadRpgArtOverrides(true);
  const _rpgCard = (id, label, thumbHtml) => {
    const custom = !!_rpgArt[id];
    return '<div class="ga-card">'
      + '<div class="ga-prev">' + thumbHtml + '</div>'
      + '<div class="ga-name">' + escapeHtml(label) + '</div>'
      + '<div class="ga-zone" tabindex="0"'
      +   ' onpaste="onRpgArtPaste(\'' + id + '\', event)"'
      +   ' ondragover="event.preventDefault(); this.classList.add(\'drag\')"'
      +   ' ondragleave="this.classList.remove(\'drag\')"'
      +   ' ondrop="onRpgArtDrop(\'' + id + '\', event)"'
      +   ' onclick="this.focus()">Click, then paste a PNG — or drop one here</div>'
      + '<div class="ga-actions"><label class="btn btn-outline ga-mini">Upload<input type="file" accept="image/*" style="display:none" onchange="onRpgArtPick(\'' + id + '\', event)"></label>'
      +   (custom ? '<button class="btn btn-ghost ga-mini" onclick="resetRpgArt(\'' + id + '\')">Reset</button>' : '')
      + '</div>'
      + '<div class="ga-status ' + (custom ? 'custom' : '') + '">' + (custom ? '● Custom' : 'Default') + '</div>'
      + '</div>';
  };
  html += '<h2 class="ga-game">🧍 Avatar &amp; Items <span style="font-weight:400;font-size:0.8rem;color:#94a3b8;">— replace the ragdoll SVGs with pixel-art PNGs</span></h2>';
  const _charPrev = (key, gender) => _rpgArt[key]
    ? '<svg viewBox="0 0 200 240" xmlns="http://www.w3.org/2000/svg"><image href="' + escapeHtml(_rpgArt[key]) + '" x="0" y="0" width="200" height="240" preserveAspectRatio="xMidYMid meet" style="image-rendering:pixelated;"/></svg>'
    : rpgAvatarSvg({}, gender);
  html += '<h3 class="ga-cat">Hero character <span style="font-weight:400;font-size:0.8rem;color:#94a3b8;">— students pick Male or Female on their hero page</span></h3><div class="ga-cards">'
    + _rpgCard('_character_male', '👦 Hero — Male', _charPrev('_character_male', 'male'))
    + _rpgCard('_character_female', '👧 Hero — Female', _charPrev('_character_female', 'female'))
    + _rpgCard('_character', 'Hero — Default (no choice yet)', _charPrev('_character', null))
    + '</div>';
  const bySlot = {};
  RPG_ITEMS.forEach(it => { (bySlot[it.slot] = bySlot[it.slot] || []).push(it); });
  ['weapon', 'shield', 'armor', 'helmet', 'accessory', 'pet'].forEach(slot => {
    const list = bySlot[slot]; if (!list || !list.length) return;
    const meta = RPG_SLOT_META[slot] || { label: slot, icon: '' };
    html += '<h3 class="ga-cat">' + (meta.icon || '') + ' ' + escapeHtml(meta.label || slot) + ' (' + list.length + ')</h3><div class="ga-cards">';
    list.forEach(it => { html += _rpgCard(it.id, it.name, rpgItemIconSvg(it)); });
    html += '</div>';
  });

  // ===== Science Spire — per-object animation slots (idle/attack/hurt/death) =====
  await loadSpireOverrides(true);
  const spireCats = {};
  SPIRE_OBJECTS.forEach(o => { (spireCats[o.cat] = spireCats[o.cat] || []).push(o); });
  html += '<h2 class="ga-game">🃏 Science Spire <span style="font-weight:400;font-size:0.8rem;color:#94a3b8;">— paste a PNG for each animation state; missing states fall back to Idle</span></h2>';
  Object.keys(spireCats).forEach(cat => {
    html += '<h3 class="ga-cat">' + cat + '</h3>';
    spireCats[cat].forEach(o => {
      html += '<div class="ga-objrow"><div class="ga-objname" style="font-weight:600;margin:6px 0;">' + o.emoji + ' ' + escapeHtml(o.label) + '</div><div class="ga-cards">';
      SPIRE_ANIMS.forEach(an => {
        const slotId = o.id + ':' + an.id;
        const safe = slotId.replace(':','-');
        const ov = _spireOverridesCache[slotId];
        const thumb = ov ? ('<img src="' + ov + '" alt="' + escapeHtml(o.label) + ' ' + an.label + '">') : ('<div style="font-size:34px;line-height:64px;text-align:center;opacity:.7;">' + o.emoji + '</div>');
        html += '<div class="ga-card" id="sgcard-' + safe + '">'
          + '<div class="ga-prev">' + thumb + '</div>'
          + '<div class="ga-name">' + an.label + '</div>'
          + '<div class="ga-zone" id="sgzone-' + safe + '" tabindex="0"'
          +   ' onpaste="onSpireObjPaste(\'' + slotId + '\', event)"'
          +   ' ondragover="event.preventDefault(); this.classList.add(\'drag\')"'
          +   ' ondragleave="this.classList.remove(\'drag\')"'
          +   ' ondrop="onSpireObjDrop(\'' + slotId + '\', event)"'
          +   ' onclick="this.focus()">Click, then paste a PNG — or drop one here</div>'
          + '<div class="ga-actions">'
          +   '<label class="btn btn-outline ga-mini">Upload<input type="file" accept="image/*" style="display:none" onchange="onSpireObjPick(\'' + slotId + '\', event)"></label>'
          +   (ov ? '<button class="btn btn-ghost ga-mini" onclick="resetSpireObj(\'' + slotId + '\')">Reset</button>' : '')
          + '</div>'
          + '<div class="ga-status ' + (ov ? 'custom' : '') + '" id="sgstatus-' + safe + '">' + (ov ? '● Custom' : 'Default') + '</div>'
          + '</div>';
      });
      html += '</div></div>';
    });
  });

  // ===== Science Spire — card art overrides (one picture per card) =====
  await loadSpireCardArt(true);
  html += spireCardArtAdminHtml();

  host.innerHTML = html;
}

async function _rpgArtApply(id, dataUrl){
  try {
    if (!/^data:image\//i.test(dataUrl)) throw new Error('Not an image');
    const scaled = await _scaleDownDataUrl(dataUrl, 256);
    const url = await uploadImageDataUrl(scaled);
    const uid = _rpgArtOwnerUid(); if (!uid) throw new Error('Not signed in');
    await setDoc(doc(db, 'users', uid, 'settings', 'rpgArt'), { overrides: { [id]: url } }, { merge: true });
    _rpgArt[id] = url;
    await loadGameAssets();
    try { if (document.querySelector('#page-character.active')) rpgRenderCharacterPage(); } catch (e) {}
    showToast('Art updated', 'success');
  } catch (e) { console.error('rpg art update', e); showToast('Update failed: ' + (e && e.message ? e.message : e), 'error'); }
}
function onRpgArtPaste(id, e){
  const items = (e.clipboardData && e.clipboardData.items) || [];
  for (const it of items){ if (it.type && it.type.startsWith('image/')){ e.preventDefault(); _raidersFileToDataUrl(it.getAsFile(), du => _rpgArtApply(id, du)); return; } }
  showToast('No image in clipboard — copy a PNG first', 'error');
}
function onRpgArtDrop(id, e){ e.preventDefault(); if (e.currentTarget) e.currentTarget.classList.remove('drag'); const file = e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0]; _raidersFileToDataUrl(file, du => _rpgArtApply(id, du)); }
function onRpgArtPick(id, e){ const file = e.target && e.target.files && e.target.files[0]; _raidersFileToDataUrl(file, du => _rpgArtApply(id, du)); if (e.target) e.target.value = ''; }
async function resetRpgArt(id){
  try {
    const uid = _rpgArtOwnerUid(); if (!uid) return;
    await setDoc(doc(db, 'users', uid, 'settings', 'rpgArt'), { overrides: { [id]: deleteField() } }, { merge: true });
    delete _rpgArt[id];
    await loadGameAssets();
    try { if (document.querySelector('#page-character.active')) rpgRenderCharacterPage(); } catch (e) {}
    showToast('Reset to default', 'success');
  } catch (e) { console.error('rpg art reset', e); showToast('Reset failed', 'error'); }
}

