// ---- Elemental affinity: 5 combat elements in a super-effective ring. Each
// deals ×2 to the one it "beats" and takes ×2 (deals ×0.5) to the one that
// beats it. Flame → Nature → Terra → Spark → Aqua → Flame.
const TCG_AFFINITY = {
  flame:  { icon: '🔥', name: 'Flame',  beats: 'nature' },
  nature: { icon: '🌿', name: 'Nature', beats: 'terra' },
  terra:  { icon: '🪨', name: 'Terra',  beats: 'spark' },
  spark:  { icon: '⚡', name: 'Spark',  beats: 'aqua' },
  aqua:   { icon: '💧', name: 'Aqua',   beats: 'flame' }
};
Object.keys(TCG_AFFINITY).forEach(k => { TCG_AFFINITY[TCG_AFFINITY[k].beats].weakTo = k; });
// Map each of the 12 flavour elements onto one of the 5 combat elements.
const TCG_ELEM_AFFINITY = {
  flame: 'flame', light: 'flame',
  aqua: 'aqua', frost: 'aqua', shadow: 'aqua',
  spark: 'spark', cosmic: 'spark', psychic: 'spark',
  terra: 'terra', metal: 'terra',
  flora: 'nature', venom: 'nature'
};
function tcgAffinity(card) { return TCG_ELEM_AFFINITY[card && card.element] || 'flame'; }
// Damage multiplier attacker→defender by the element ring.
function tcgElemMult(attCard, defCard) {
  const a = tcgAffinity(attCard), d = tcgAffinity(defCard);
  if (TCG_AFFINITY[a] && TCG_AFFINITY[a].beats === d) return 2;
  if (TCG_AFFINITY[d] && TCG_AFFINITY[d].beats === a) return 0.5;
  return 1;
}
