// a second time.
async function _tcgGenLogo() {
  const got = await _tcgGenClean(h => tcgLogoPrompt(h), null, 'realm logo', true, TCG_LOGO_SCREEN);
  await _tcgArtStore(TCG_LOGO_SLOT, got.url, { cleaned: true });
  return got.url;
}
// Wherever the mark is worn: the Realm of Embers page header, and the nav door
