    + '</div>';
  const num = document.getElementById('tcgLoreCount');
  if (num) num.textContent = 'Page ' + (_tcgLorePage + 1) + ' of ' + pages.length;
  const prev = document.getElementById('tcgLorePrev'), next = document.getElementById('tcgLoreNext');
