    + '<div class="tcg-quiz-opts">'
    + q.opts.map((o, idx) => '<button type="button" class="tcg-quiz-opt" data-i="' + idx + '" onclick="_tcgQuizAnswer(' + idx + ')">'
        + '<span class="tcg-quiz-let">' + (idx + 1) + '</span>' + escapeHtml(o) + '</button>').join('')
    + '</div>'
