    + '<div class="tcg-team-slots">' + slots + '</div>'
    + '<div class="tcg-team-power">Team power: <b>' + tcgTeamPower(s.team).toLocaleString() + '</b>' + (s.team.length === 5 ? ' · ready for battle ⚔️' : ' · pick ' + (5 - s.team.length) + ' more') + '</div>'
    + tcgArtifactPickerHtml(s)
