function ppClone(o){ return JSON.parse(JSON.stringify(o)); }
function ppDefaults(){ return { questions: PP_SEED_Q.map(ppClone), recurring: PP_SEED_R.map(ppClone) }; }
function ppQuestions(){ return (ppData && Array.isArray(ppData.questions)) ? ppData.questions : []; }
function ppRecurring(){ return (ppData && Array.isArray(ppData.recurring)) ? ppData.recurring : []; }
function ppYears(){ return [...new Set(ppQuestions().map(q => String(q.year)))].sort(); }
function ppNextN(year){ const ns = ppQuestions().filter(q => String(q.year) === String(year)).map(q => Number(q.n) || 0); return ns.length ? Math.max.apply(null, ns) + 1 : 1; }
function ppNewId(){ return 'u_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 7); }

function ppKey(q){ return q.id; }
function ppSkillName(t){ return PP_SKILL[t] || t || '—'; }
function ppTheme(topic){ return PP_THEME[topic] || 'diversity'; }
function ppThemeColor(topic){ return PP_THEME_C[ppTheme(topic)]; }
function ppLevel(topic){ try { return getTopicLevel(topic); } catch(_) { return ''; } }
function ppFindQ(id){ return ppQuestions().find(q => q.id === id); }
// The topic used across the analysis (chart, bars, topic worksheets): the
// ATTACHED bank question's topic — the live value the admin edits — when a
// question is attached, otherwise the past-paper record's own topic. This way
// changing a question's topic in the editor immediately re-buckets everything.
function ppTopicOf(q){ if (!q) return ''; const bq = ppBankQ(q.id); return (bq && bq.topic) ? bq.topic : (q.topic || ''); }
function ppIsAdmin(){ return !!(currentUser && currentUser.role === 'admin'); }
function ppOwnerUid(){ return ppIsAdmin() ? (currentUser && currentUser.uid) : adminUid; }
function ppBankQ(id){ const b = paperMap[id]; return b ? questionBank.find(q => q.id === b) : null; }

// ---- Question success rate (correct attempts / total attempts, whole %) ----
// Backed by the shared per-question attempt stats (_qAttemptStats), which are
// written for EVERY marked question on EVERY platform — Quick/Topical/worksheet
// practice, past-paper practice and all game modes (defenders/raiders/legends/
// slayers) — so this one accessor reflects a student's live accuracy anywhere.
// Returns a whole-number percentage, or null if the question was never attempted.
function questionPercent(qid){
  const r = (typeof _qAttemptStats !== 'undefined' && _qAttemptStats) ? _qAttemptStats[String(qid == null ? '' : qid)] : null;
  if (!r || !r.n) return null;
  return Math.round((r.correct / r.n) * 100);
}
// Full picture for a question id: { attempts, correct, percent }. percent is null
// when there are no attempts yet.
function questionStats(qid){
  const r = (typeof _qAttemptStats !== 'undefined' && _qAttemptStats) ? _qAttemptStats[String(qid == null ? '' : qid)] : null;
  const n = r ? r.n : 0, correct = r ? r.correct : 0;
  return { attempts: n, correct: correct, percent: n ? Math.round((correct / n) * 100) : null };
}

// ---- Past-paper difficulty (admin-set, colour-codes the question chips) ----
// Difficulty lives on each past-paper question as q.diff ∈ 'easy'|'moderate'|'hard'
// and only ever applies inside the Past Papers analysis interface.
function ppDiff(q){ const d = q && q.diff; return (d === 'easy' || d === 'moderate' || d === 'hard') ? d : ''; }
function ppDiffClass(q){ const d = ppDiff(q); return d ? ' pp-diff-' + d : ''; }
// Set (or clear) the difficulty of ONE past-paper question and persist it.
// level: 'easy' | 'moderate' | 'hard'  (anything else clears it).
async function ppSetDifficulty(id, level){
  if (!ppIsAdmin()) { showToast('Only admins can set difficulty', 'error'); return; }
  const q = ppFindQ(id); if (!q) return;
  const lv = (level === 'easy' || level === 'moderate' || level === 'hard') ? level : '';
  if (lv) q.diff = lv; else delete q.diff;
  await savePaperData();
  ppHoverHide();
  ppRenderBody();
}

async function loadPaperData(force){
  if (_ppDataLoaded && !force) return;
  ppData = ppDefaults();
  try {
    const uid = ppOwnerUid();
    if (uid && db) {
      const snap = await getDoc(doc(db, 'users', uid, 'settings', 'paperData'));
      if (snap.exists() && snap.data()) {
        const d = snap.data();
        if (Array.isArray(d.questions) && d.questions.length) ppData.questions = d.questions;
        if (Array.isArray(d.recurring)) ppData.recurring = d.recurring;
      }
    }
  } catch (e) { console.warn('paperData load', e); }
  ppMergeSeedContent();   // bring in past-year papers shipped in code that a saved copy predates
  _ppDataLoaded = true;
}
// Specific seed question ids to backfill even into a YEAR the saved data already
// has (we normally only add whole new years). Used when we ship questions that
// were missing from a paper we'd already added — e.g. the 2025 Booklet A Q1–Q3
// placeholders added after the rest of 2025 shipped. Listed explicitly so this
// never resurrects a question the admin deliberately deleted.
const PP_BACKFILL_IDS = new Set([
  's_2025_1', 's_2025_2', 's_2025_3',                       // real Q1–Q3 (replace earlier placeholders)
  's_2025_29', 's_2025_30', 's_2025_31', 's_2025_32', 's_2025_33', 's_2025_34',
  's_2025_35', 's_2025_36', 's_2025_37', 's_2025_38', 's_2025_39', 's_2025_40'  // 2025 Booklet B (OEQ)
]);
// A saved paperData copy (once an admin edits difficulty/attachments) replaces the
// built-in seed, so a whole new past-year paper added to PP_SEED_Q would never show.
// Merge in every seed question for any YEAR the saved data doesn't have yet (this
// won't resurrect individually-deleted questions inside an existing year), plus any
// explicitly-listed PP_BACKFILL_IDS still missing, and add those new questions'
// recurring-concept links without touching existing years' notes. Also refresh any
// backfill question the admin still has only as an empty placeholder (no answer yet).
function ppMergeSeedContent(){
  try {
    const q = Array.isArray(ppData.questions) ? ppData.questions : (ppData.questions = []);
    const savedYears = new Set(q.map(x => String(x.year)));
    const present = new Set(q.map(x => x.id));
    // A seed question whose id is already saved is NEVER re-added, even if its
    // year label no longer matches — otherwise re-labelling a paper's year in
    // the whole-paper editor would resurrect the entire original paper.
    const addQ = PP_SEED_Q.filter(s => !savedYears.has(String(s.year)) && !present.has(s.id));
    const addIds = new Set(addQ.map(s => s.id));
    const backfill = PP_SEED_Q.filter(s => PP_BACKFILL_IDS.has(s.id) && !present.has(s.id) && !addIds.has(s.id));
    // Upgrade any backfill question the admin still has only as an empty placeholder
    // (blank answer AND blank detail) to the real shipped content — keeps their diff.
    PP_SEED_Q.forEach(s => {
      if (!PP_BACKFILL_IDS.has(s.id)) return;
      const cur = q.find(x => x.id === s.id);
      if (cur && !String(cur.ans || '').trim() && !String(cur.detail || '').trim()) {
        const keepDiff = cur.diff;
        Object.assign(cur, ppClone(s));
        if (keepDiff) cur.diff = keepDiff; else delete cur.diff;
      }
    });
    const toAdd = addQ.concat(backfill);
    if (!toAdd.length) return;
    ppData.questions = q.concat(toAdd.map(ppClone));
    const newIds = new Set(toAdd.map(s => s.id));
    const rec = Array.isArray(ppData.recurring) ? ppData.recurring : (ppData.recurring = []);
    const byId = {}; rec.forEach(r => { if (r && r.id) byId[r.id] = r; });
    PP_SEED_R.forEach(sr => {
      const cur = byId[sr.id];
      if (!cur) { rec.push(ppClone(sr)); return; }
      if (!Array.isArray(sr.hits)) return;
      if (!Array.isArray(cur.hits)) cur.hits = [];
      const have = new Set(cur.hits);
      sr.hits.forEach(h => { if (newIds.has(h) && !have.has(h)) { cur.hits.push(h); have.add(h); } });
    });
  } catch (e) { console.warn('pp seed merge', e); }
}

